(315529,35059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лампа зазвичай світить м''яко, але вчора ввечері вона ... як палаюче сонце!'::text,'світила'::text,'світить'::text,NULL::text,'Лампа зазвичай світить м''яко, але вчора ввечері вона світила як палаюче сонце!'::text),
