(315527,35059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, la lampe brille doucement, mais hier soir elle ... comme un soleil en feu !'::text,'a brillé'::text,'brille'::text,NULL::text,'D''habitude, la lampe brille doucement, mais hier soir elle a brillé comme un soleil en feu !'::text),
(315530,35059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lamba genelde yumuşak parlar ama dün gece yanan bir güneş gibi ...!'::text,'parladı'::text,'parlar'::text,NULL::text,'Lamba genelde yumuşak parlar ama dün gece yanan bir güneş gibi parladı!'::text),
(315531,35059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lámpa általában lágyan világít, de tegnap este úgy ..., mint egy égő nap!'::text,'világított'::text,'világít'::text,NULL::text,'A lámpa általában lágyan világít, de tegnap este úgy világított, mint egy égő nap!'::text),
(315534,35060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kronleuchter ... über der Frau im silbernen Kleid.'::text,'leuchtet'::text,'leuchtet'::text,'leuchtet'::text,'Der Kronleuchter leuchtet über der Frau im silbernen Kleid.'::text),
(315538,35060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люстра ... над жінкою в срібній сукні.'::text,'світить'::text,'світить'::text,'світить'::text,'Люстра світить над жінкою в срібній сукні.'::text),
(315537,35060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lámpara de araña ... sobre la mujer del vestido plateado.'::text,'está brillando'::text,'brilla'::text,'está brillando'::text,'La lámpara de araña está brillando sobre la mujer del vestido plateado.'::text),
(315536,35060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le lustre ... au-dessus de la femme en robe argentée.'::text,'est en train de briller'::text,'brille'::text,'est en train de briller'::text,'Le lustre est en train de briller au-dessus de la femme en robe argentée.'::text),
(315539,35060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avize gümüş elbiseli kadının üstünde ...'::text,'parlıyor'::text,'parlar'::text,'parlıyor'::text,'Avize gümüş elbiseli kadının üstünde parlıyor.'::text),
(315540,35060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csillár ... az ezüst ruhás nő fölött.'::text,'ragyog'::text,'ragyog'::text,'ragyog'::text,'A csillár ragyog az ezüst ruhás nő fölött.'::text),
(315543,35061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schreibtischlampe bleibt sonst aus, aber heute Abend ... sie auf die Bücher.'::text,'leuchtet'::text,'leuchtet'::text,NULL::text,'Die Schreibtischlampe bleibt sonst aus, aber heute Abend leuchtet sie auf die Bücher.'::text),
(315547,35061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Настільна лампа зазвичай вимкнена, але сьогодні ввечері вона ... на книжки.'::text,'світить'::text,'світить'::text,NULL::text,'Настільна лампа зазвичай вимкнена, але сьогодні ввечері вона світить на книжки.'::text),
(315546,35061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lámpara de escritorio normalmente se queda apagada, pero esta noche ... los libros.'::text,'está iluminando'::text,'ilumina'::text,NULL::text,'La lámpara de escritorio normalmente se queda apagada, pero esta noche está iluminando los libros.'::text),
(315545,35061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lampe de bureau reste éteinte d''habitude, mais ce soir elle ... sur les livres.'::text,'est en train de briller'::text,'brille'::text,NULL::text,'La lampe de bureau reste éteinte d''habitude, mais ce soir elle est en train de briller sur les livres.'::text),
(315548,35061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Masa lambası genelde kapalı kalır ama bu akşam kitapların üstüne ...'::text,'parlıyor'::text,'parlar'::text,NULL::text,'Masa lambası genelde kapalı kalır ama bu akşam kitapların üstüne parlıyor.'::text),
(315549,35061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az asztali lámpa általában ki van kapcsolva, de ma este ... a könyvekre.'::text,'világít'::text,'világít'::text,NULL::text,'Az asztali lámpa általában ki van kapcsolva, de ma este világít a könyvekre.'::text),
(315561,35063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, sie greift nach der Lampe, die ... gleich leuchten, Alter.'::text,'wird'::text,'wird'::text,'wird'::text,'Ey, sie greift nach der Lampe, die wird gleich leuchten, Alter.'::text),
(315565,35063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона тягнеться до лампи, та за секунду ..., бро.'::text,'засвітиться'::text,'засвітиться'::text,'засвітиться'::text,'Йо, вона тягнеться до лампи, та за секунду засвітиться, бро.'::text),
(315564,35063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, está cogiendo la lámpara, en un segundo ..., tío.'::text,'va a brillar'::text,'brillará'::text,'va a brillar'::text,'Oye, está cogiendo la lámpara, en un segundo va a brillar, tío.'::text),
(315563,35063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, elle attrape la lampe, elle ... dans une seconde, frère.'::text,'va briller'::text,'brillera'::text,'va briller'::text,'Wesh, elle attrape la lampe, elle va briller dans une seconde, frère.'::text),
(315566,35063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak, lambaya uzanıyor, bir saniyeye ..., kanka.'::text,'parlayacak'::text,'parlayacak'::text,'parlayacak'::text,'Bak, lambaya uzanıyor, bir saniyeye parlayacak, kanka.'::text),
(315567,35063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a lámpáért nyúl, egy másodperc múlva ..., tesó.'::text,'világítani fog'::text,'világítani fog'::text,'világítani fog'::text,'Figyu, a lámpáért nyúl, egy másodperc múlva világítani fog, tesó.'::text),
(315570,35064,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan für heute Abend: 500 Gäste, also ... der Kronleuchter die ganze Nacht leuchten.'::text,'wird'::text,'wird'::text,NULL::text,'Plan für heute Abend: 500 Gäste, also wird der Kronleuchter die ganze Nacht leuchten.'::text),
(315574,35064,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Графік на сьогоднішній вечір: 500 гостей, тож люстра ... світити всю ніч.'::text,'збирається'::text,'буде'::text,NULL::text,'Графік на сьогоднішній вечір: 500 гостей, тож люстра збирається світити всю ніч.'::text),
