(315576,35064,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mai esti program: 500 vendég, ezért a csillár egész éjjel ... ragyogni.'::text,'fog'::text,'fog'::text,NULL::text,'A mai esti program: 500 vendég, ezért a csillár egész éjjel fog ragyogni.'::text),
(315579,35065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kronleuchter ... heute Abend leuchten, weil der Saal nachts dunkel ist.'::text,'muss'::text,'muss'::text,'sollte'::text,'Der Kronleuchter muss heute Abend leuchten, weil der Saal nachts dunkel ist.'::text),
(315583,35065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люстра ... світити сьогодні ввечері, бо вночі в залі темно.'::text,'має'::text,'мусить'::text,'мала б'::text,'Люстра має світити сьогодні ввечері, бо вночі в залі темно.'::text),
(315582,35065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lámpara de araña ... brillar esta noche porque el salón está oscuro de noche.'::text,'tiene que'::text,'debe'::text,'debería'::text,'La lámpara de araña tiene que brillar esta noche porque el salón está oscuro de noche.'::text),
(315581,35065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le lustre ... briller ce soir parce que la salle est sombre la nuit.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le lustre doit briller ce soir parce que la salle est sombre la nuit.'::text),
(315584,35065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Salon geceleri karanlık olduğu için avize bu akşam ...'::text,'parlamak zorunda'::text,'parlamalı'::text,'parlamalı'::text,'Salon geceleri karanlık olduğu için avize bu akşam parlamak zorunda.'::text),
