(301701,33523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lacht sonst über Witze, also ... er jetzt über einen Witz.'::text,'lacht'::text,'lacht'::text,NULL::text,'Er lacht sonst über Witze, also lacht er jetzt über einen Witz.'::text),
(301705,33523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зазвичай сміється з жартів, тож зараз він ... з жарту.'::text,'сміється'::text,'сміється'::text,NULL::text,'Він зазвичай сміється з жартів, тож зараз він сміється з жарту.'::text),
(301704,33523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente se ríe con los chistes, así que ahora ... de un chiste.'::text,'se está riendo'::text,'se ríe'::text,NULL::text,'Normalmente se ríe con los chistes, así que ahora se está riendo de un chiste.'::text),
(301703,33523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il rit des blagues, donc maintenant il ... d''une blague.'::text,'est en train de rire'::text,'rit'::text,NULL::text,'D''habitude il rit des blagues, donc maintenant il est en train de rire d''une blague.'::text),
(301706,33523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde şakalara güler, bu yüzden şimdi bir şakaya ...'::text,'gülüyor'::text,'güler'::text,NULL::text,'Genelde şakalara güler, bu yüzden şimdi bir şakaya gülüyor.'::text),
(301707,33523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában nevet a vicceken, ezért most is ... egy viccen.'::text,'nevet'::text,'nevet'::text,NULL::text,'Általában nevet a vicceken, ezért most is nevet egy viccen.'::text),
(301710,33524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Witz bringt mich um! Ich ... für immer lachen!'::text,'werde'::text,'werde'::text,'werde'::text,'Dieser Witz bringt mich um! Ich werde für immer lachen!'::text),
(301714,33524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей жарт мене вбиває! Я ... вічно!'::text,'сміятимусь'::text,'сміятимусь'::text,'сміятимусь'::text,'Цей жарт мене вбиває! Я сміятимусь вічно!'::text),
(301713,33524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este chiste me está matando! ¡... para siempre!'::text,'Me reiré'::text,'Me reiré'::text,'Me reiré'::text,'¡Este chiste me está matando! ¡Me reiré para siempre!'::text),
(301712,33524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette blague me tue ! Je ... pour toujours !'::text,'rirai'::text,'rirai'::text,'rirai'::text,'Cette blague me tue ! Je rirai pour toujours !'::text),
(301715,33524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu şaka beni öldürüyor! Sonsuza kadar ...!'::text,'güleceğim'::text,'güleceğim'::text,'güleceğim'::text,'Bu şaka beni öldürüyor! Sonsuza kadar güleceğim!'::text),
(301716,33524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a vicc kinyír! Örökké ... nevetni!'::text,'fogok'::text,'fogok'::text,'fogok'::text,'Ez a vicc kinyír! Örökké fogok nevetni!'::text),
(301719,33525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ganze Klasse schreit! Dieser Witz ... die Stunde ruinieren!'::text,'wird'::text,'werden'::text,'wird'::text,'Die ganze Klasse schreit! Dieser Witz wird die Stunde ruinieren!'::text),
(301723,33525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Весь клас кричить! Цей жарт ... урок!'::text,'зіпсує'::text,'зіпсують'::text,'зіпсує'::text,'Весь клас кричить! Цей жарт зіпсує урок!'::text),
(301722,33525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Toda la clase está gritando! ¡Este chiste ... la clase!'::text,'va a arruinar'::text,'van a arruinar'::text,'va a arruinar'::text,'¡Toda la clase está gritando! ¡Este chiste va a arruinar la clase!'::text),
(301721,33525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la classe hurle ! Cette blague ... le cours !'::text,'va gâcher'::text,'vont gâcher'::text,'va gâcher'::text,'Toute la classe hurle ! Cette blague va gâcher le cours !'::text),
(301724,33525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sınıf bağırıyor! Bu şaka dersi ...!'::text,'mahvedecek'::text,'mahvedecekler'::text,'mahvedecek'::text,'Bütün sınıf bağırıyor! Bu şaka dersi mahvedecek!'::text),
(301725,33525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész osztály sikít! Ez a vicc tönkre ... tenni az órát!'::text,'fogja'::text,'fogják'::text,'fogja'::text,'Az egész osztály sikít! Ez a vicc tönkre fogja tenni az órát!'::text),
(301728,33526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Lehrer steht an der Tür! Er ... den Witz hören! Katastrophe!'::text,'wird'::text,'wird'::text,NULL::text,'Der Lehrer steht an der Tür! Er wird den Witz hören! Katastrophe!'::text),
(301732,33526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учитель біля дверей! Він ... жарт! Катастрофа!'::text,'почує'::text,'почує'::text,NULL::text,'Учитель біля дверей! Він почує жарт! Катастрофа!'::text),
(301731,33526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El profe está en la puerta! ¡... el chiste! ¡Desastre!'::text,'Va a oír'::text,'Oirá'::text,NULL::text,'¡El profe está en la puerta! ¡Va a oír el chiste! ¡Desastre!'::text),
(301730,33526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le prof est à la porte ! Il ... la blague ! Catastrophe !'::text,'va entendre'::text,'entendra'::text,NULL::text,'Le prof est à la porte ! Il va entendre la blague ! Catastrophe !'::text),
(301733,33526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğretmen kapıda! Şakayı ...! Felaket!'::text,'duyacak'::text,'duyacak'::text,NULL::text,'Öğretmen kapıda! Şakayı duyacak! Felaket!'::text),
(301734,33526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tanár az ajtóban van! ... a viccet! Katasztrófa!'::text,'Meg fogja hallani'::text,'Meg fogja hallani'::text,NULL::text,'A tanár az ajtóban van! Meg fogja hallani a viccet! Katasztrófa!'::text),
(301737,33527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend war nach einem einzigen Witz so viel ... in der Klasse.'::text,'Gelächter'::text,'Gelächter'::text,'Witze'::text,'Hör mal, anscheinend war nach einem einzigen Witz so viel Gelächter in der Klasse.'::text),
(301741,33527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, після одного жарту в класі було стільки ...'::text,'сміху'::text,'сміху'::text,'жартів'::text,'Слухай, кажуть, після одного жарту в класі було стільки сміху.'::text),
(301740,33527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer hubo tanta ... en clase después de un solo chiste.'::text,'risa'::text,'risa'::text,'chistes'::text,'Oye, al parecer hubo tanta risa en clase después de un solo chiste.'::text),
(301739,33527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il y a eu tellement de ... en classe après une seule blague.'::text,'rires'::text,'rires'::text,'blagues'::text,'Écoute, apparemment il y a eu tellement de rires en classe après une seule blague.'::text),
(301742,33527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya tek bir şakadan sonra sınıfta çok fazla ... vardı.'::text,'kahkaha'::text,'kahkahalar'::text,'şakalar'::text,'Dinle, güya tek bir şakadan sonra sınıfta çok fazla kahkaha vardı.'::text),
(301743,33527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag egyetlen vicc után annyi ... volt az osztályban.'::text,'nevetés'::text,'nevetés'::text,'vicc'::text,'Figyelj, állítólag egyetlen vicc után annyi nevetés volt az osztályban.'::text),
(301746,33528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, er hat ... Witze auf dem Handy.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Bestie, ich hab gehört, er hat viele Witze auf dem Handy.'::text),
(301750,33528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, я чула, у нього в телефоні ... жартів.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Подружко, я чула, у нього в телефоні багато жартів.'::text),
(301749,33528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que tiene ... chistes en el móvil.'::text,'muchos'::text,'mucho'::text,'cualquier'::text,'Amiga, he oído que tiene muchos chistes en el móvil.'::text),
(301748,33528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît qu''il a ... blagues sur son téléphone.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quelles'::text,'Ma belle, il paraît qu''il a beaucoup de blagues sur son téléphone.'::text),
(301751,33528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki telefonunda ... şaka varmış.'::text,'çok'::text,'çok'::text,'herhangi'::text,'Kanka, duydum ki telefonunda çok şaka varmış.'::text),
(301752,33528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy ... vicc van a telefonján.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Csajszi, azt hallottam, hogy sok vicc van a telefonján.'::text),
(301755,33529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf seinem Handy ... ein lustiger Witz.'::text,'ist'::text,'sind'::text,'sein'::text,'Auf seinem Handy ist ein lustiger Witz.'::text),
(301759,33529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У його телефоні ... смішний жарт.'::text,'є'::text,'є'::text,'бути'::text,'У його телефоні є смішний жарт.'::text),
(301758,33529,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un chiste gracioso en su móvil.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay un chiste gracioso en su móvil.'::text),
(301757,33529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... une blague drôle sur son téléphone.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a une blague drôle sur son téléphone.'::text),
(301760,33529,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonunda komik bir şaka ...'::text,'var'::text,'var'::text,'olmak'::text,'Telefonunda komik bir şaka var.'::text),
(301761,33529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A telefonján ... egy jó vicc.'::text,'van'::text,'vannak'::text,'lenni'::text,'A telefonján van egy jó vicc.'::text),
(321717,35747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Jonglieren ist ... Talent, kein Glück, Alter.'::text,'ein'::text,'das'::text,'ein'::text,'Nee, Jonglieren ist ein Talent, kein Glück, Alter.'::text),
(321721,35747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, жонглювання — це ... талант, а не удача, бро.'::text,''::text,NULL::text,NULL::text,'Не, жонглювання — це талант, а не удача, бро.'::text),
(321720,35747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, hacer malabares es ... talento, no suerte, tío.'::text,'un'::text,'el'::text,'un'::text,'Qué va, hacer malabares es un talento, no suerte, tío.'::text),
(321719,35747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, jongler c''est ... talent, pas de la chance, frère.'::text,'un'::text,'le'::text,'un'::text,'Non, jongler c''est un talent, pas de la chance, frère.'::text),
(321722,35747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, jonglörlük ... yetenek, şans değil.'::text,'bir'::text,NULL::text,'bir'::text,'Yok kanka, jonglörlük bir yetenek, şans değil.'::text),
(321723,35747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, a zsonglőrködés ... tehetség, nem szerencse, tesó.'::text,'egy'::text,'a'::text,'egy'::text,'Á, a zsonglőrködés egy tehetség, nem szerencse, tesó.'::text),
(321726,35748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Talent-Review: ... Bälle bleiben 60 Sekunden in der Luft.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Talent-Review: Diese Bälle bleiben 60 Sekunden in der Luft.'::text),
(321730,35748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оцінка таланту: ... м''ячі тримаються в повітрі 60 секунд.'::text,'Ці'::text,'Цей'::text,'Той'::text,'Оцінка таланту: Ці м''ячі тримаються в повітрі 60 секунд.'::text),
(321729,35748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evaluación de talento: ... pelotas se quedan en el aire 60 segundos.'::text,'Estas'::text,'Esta'::text,'Esa'::text,'Evaluación de talento: Estas pelotas se quedan en el aire 60 segundos.'::text),
(321728,35748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bilan talent : ... balles restent en l''air 60 secondes.'::text,'Ces'::text,'Cette'::text,'Cette'::text,'Bilan talent : Ces balles restent en l''air 60 secondes.'::text),
(321731,35748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetenek değerlendirmesi: ... toplar 60 saniye havada kalıyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Yetenek değerlendirmesi: Bu toplar 60 saniye havada kalıyor.'::text),
(321732,35748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tehetségértékelés: ... a labdák 60 másodpercig a levegőben maradnak.'::text,'Ezek'::text,'Ez'::text,'Az'::text,'Tehetségértékelés: Ezek a labdák 60 másodpercig a levegőben maradnak.'::text),
(321735,35749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jongleur zeigt ... Talent, also sehen die Freunde es.'::text,'ihr'::text,'sein'::text,'unser'::text,'Der Jongleur zeigt ihr Talent, also sehen die Freunde es.'::text),
(321739,35749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жонглер показує ... талант, тож друзі його бачать.'::text,'свій'::text,'свій'::text,'свій'::text,'Жонглер показує свій талант, тож друзі його бачать.'::text),
(321738,35749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El malabarista muestra ... talento, así que los amigos lo ven.'::text,'su'::text,'su'::text,'nuestro'::text,'El malabarista muestra su talento, así que los amigos lo ven.'::text),
(321737,35749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jongleur montre ... talent, alors les amis le voient.'::text,'leur'::text,'son'::text,'notre'::text,'Le jongleur montre leur talent, alors les amis le voient.'::text),
(321740,35749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jonglör ... yeteneğini gösteriyor, böylece arkadaşlar onu görüyor.'::text,'onların'::text,'onun'::text,'bizim'::text,'Jonglör onların yeteneğini gösteriyor, böylece arkadaşlar onu görüyor.'::text),
(321741,35749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zsonglőr megmutatja a ..., így a barátok látják.'::text,'tehetségüket'::text,'tehetségét'::text,'tehetségünket'::text,'A zsonglőr megmutatja a tehetségüket, így a barátok látják.'::text),
(321744,35750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie jonglieren ... Park mit so viel Talent, das ist völlig irre!'::text,'im'::text,'auf dem'::text,'am'::text,'Sie jonglieren im Park mit so viel Talent, das ist völlig irre!'::text),
(321748,35750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони жонглюють ... парку з таким талантом, це просто нереально!'::text,'у'::text,'на'::text,'біля'::text,'Вони жонглюють у парку з таким талантом, це просто нереально!'::text),
(321747,35750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hacen malabares ... el parque con tanto talento, es totalmente irreal!'::text,'en'::text,'sobre'::text,'a'::text,'¡Hacen malabares en el parque con tanto talento, es totalmente irreal!'::text),
(321746,35750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils jonglent ... parc avec un tel talent, c''est complètement irréel !'::text,'dans le'::text,'sur le'::text,'au'::text,'Ils jonglent dans le parc avec un tel talent, c''est complètement irréel !'::text),
(321749,35750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parkın ... öyle yetenekle jonglörlük yapıyorlar ki, resmen inanılmaz!'::text,'içinde'::text,'üstünde'::text,NULL::text,'Parkın içinde öyle yetenekle jonglörlük yapıyorlar ki, resmen inanılmaz!'::text),
(321750,35750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan tehetséggel zsonglőrködnek a ..., hogy az egyszerűen hihetetlen!'::text,'parkban'::text,'parkon'::text,'parknál'::text,'Olyan tehetséggel zsonglőrködnek a parkban, hogy az egyszerűen hihetetlen!'::text),
(321753,35751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der talentierte Jongleur hält ... Bälle in der Luft.'::text,'drei'::text,'dritten'::text,'Dreien'::text,'Der talentierte Jongleur hält drei Bälle in der Luft.'::text),
(321757,35751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Талановитий жонглер тримає в повітрі ... м''ячі.'::text,'три'::text,'третій'::text,'трійки'::text,'Талановитий жонглер тримає в повітрі три м''ячі.'::text),
(321756,35751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El malabarista con talento mantiene ... pelotas en el aire.'::text,'tres'::text,'tercera'::text,'tres'::text,'El malabarista con talento mantiene tres pelotas en el aire.'::text),
(321755,35751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jongleur talentueux garde ... balles en l''air.'::text,'trois'::text,'troisième'::text,'trois'::text,'Le jongleur talentueux garde trois balles en l''air.'::text),
(321758,35751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetenekli jonglör ... topu havada tutuyor.'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'Yetenekli jonglör üç topu havada tutuyor.'::text),
(321759,35751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tehetséges zsonglőr ... labdát tart a levegőben.'::text,'három'::text,'harmadik'::text,'hármasok'::text,'A tehetséges zsonglőr három labdát tart a levegőben.'::text),
(321771,35753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, echt: Die Freunde sitzen mit so ... Talent auf dem Rasen.'::text,'viel'::text,'viele'::text,'irgendwelchem'::text,'Super gemacht, echt: Die Freunde sitzen mit so viel Talent auf dem Rasen.'::text),
(321775,35753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, звісно: друзі сидять на траві, маючи так ... таланту.'::text,'багато'::text,'багато'::text,'будь-якого'::text,'Чудова робота, звісно: друзі сидять на траві, маючи так багато таланту.'::text),
(321774,35753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, obviamente: los amigos se sientan en el césped con ... talento.'::text,'tanto'::text,'tantos'::text,'cualquier'::text,'Buen trabajo, obviamente: los amigos se sientan en el césped con tanto talento.'::text),
(321773,35753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, évidemment : les amis sont assis sur l''herbe avec ... talent.'::text,'tant de'::text,'tant de'::text,'n''importe quel'::text,'Bravo, évidemment : les amis sont assis sur l''herbe avec tant de talent.'::text),
(321776,35753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, belli ki: arkadaşlar çimlerde o kadar ... yetenekle oturuyor.'::text,'çok'::text,'çok'::text,'herhangi'::text,'Harika iş, belli ki: arkadaşlar çimlerde o kadar çok yetenekle oturuyor.'::text),
(321777,35753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, nyilván: a barátok olyan ... tehetséggel ülnek a füvön.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Szép munka, nyilván: a barátok olyan sok tehetséggel ülnek a füvön.'::text),
(303222,33692,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ..., mit 3 Bällen zu jonglieren. Das ist das Ziel.'::text,'lernt'::text,'lernen'::text,'lernend'::text,'Er lernt, mit 3 Bällen zu jonglieren. Das ist das Ziel.'::text),
(303226,33692,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... жонглювати 3 м''ячами. Це мета.'::text,'вчиться'::text,'вчитися'::text,'вчачись'::text,'Він вчиться жонглювати 3 м''ячами. Це мета.'::text),
(303225,33692,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... a hacer malabares con 3 pelotas. Ese es el objetivo.'::text,'aprende'::text,'aprender'::text,'aprendiendo'::text,'Él aprende a hacer malabares con 3 pelotas. Ese es el objetivo.'::text),
(303224,33692,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à jongler avec 3 balles. C''est l''objectif.'::text,'apprend'::text,'apprendre'::text,'apprenant'::text,'Il apprend à jongler avec 3 balles. C''est l''objectif.'::text),
(303227,33692,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'3 topla jonglörlük yapmayı ...; hedef bu.'::text,'öğrenir'::text,'öğrenmek'::text,'öğrenerek'::text,'3 topla jonglörlük yapmayı öğrenir; hedef bu.'::text),
(303228,33692,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... 3 labdával zsonglőrködni. Ez a cél.'::text,'Tanul'::text,'Tanulni'::text,'Tanuló'::text,'Tanul 3 labdával zsonglőrködni. Ez a cél.'::text),
(303231,33693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... Jonglieren lernen, weil die Bälle zum Jonglieren sind.'::text,'kann'::text,'kann'::text,'kann'::text,'Er kann Jonglieren lernen, weil die Bälle zum Jonglieren sind.'::text),
(303235,33693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... навчитися жонглювати, бо м''ячі для жонглювання.'::text,'може'::text,'може'::text,'може'::text,'Він може навчитися жонглювати, бо м''ячі для жонглювання.'::text),
(303234,33693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... aprender malabares, porque las pelotas son para hacer malabares.'::text,'puede'::text,'puede'::text,'puede'::text,'Él puede aprender malabares, porque las pelotas son para hacer malabares.'::text),
(303233,33693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... apprendre à jongler, parce que les balles servent à jongler.'::text,'peut'::text,'peut'::text,'peut'::text,'Il peut apprendre à jongler, parce que les balles servent à jongler.'::text),
(303236,33693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jonglörlüğü ..., çünkü toplar jonglörlük için.'::text,'öğrenebilir'::text,'öğrenebilir'::text,'öğrenebilir'::text,'Jonglörlüğü öğrenebilir, çünkü toplar jonglörlük için.'::text),
(303237,33693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meg ... tanulni zsonglőrködni, mert a labdák zsonglőrködésre valók.'::text,'tud'::text,'tud'::text,'tud'::text,'Meg tud tanulni zsonglőrködni, mert a labdák zsonglőrködésre valók.'::text),
(303249,33695,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... er endlich zu fangen! Der absolut beste Tag!'::text,'lernte'::text,'lernt'::text,'lernen'::text,'Gestern lernte er endlich zu fangen! Der absolut beste Tag!'::text),
(303253,33695,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора він нарешті ... ловити! Найкращий день!'::text,'навчився'::text,'вчиться'::text,'вчитися'::text,'Учора він нарешті навчився ловити! Найкращий день!'::text),
(303252,33695,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer por fin ... a atrapar! ¡El mejor día de todos!'::text,'aprendió'::text,'aprende'::text,'aprender'::text,'¡Ayer por fin aprendió a atrapar! ¡El mejor día de todos!'::text),
(303251,33695,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, il ... enfin à attraper ! Le meilleur jour de tous !'::text,'a appris'::text,'apprend'::text,'apprendre'::text,'Hier, il a appris enfin à attraper ! Le meilleur jour de tous !'::text),
(303254,33695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün sonunda yakalamayı ...! Kesinlikle en güzel gün!'::text,'öğrendi'::text,'öğrenir'::text,'öğrenmek'::text,'Dün sonunda yakalamayı öğrendi! Kesinlikle en güzel gün!'::text),
(303255,33695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap végre ... elkapni! A lehető legjobb nap!'::text,'megtanult'::text,'tanul'::text,'tanulni'::text,'Tegnap végre megtanult elkapni! A lehető legjobb nap!'::text),
(303267,33697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade mit ihrer Hilfe zu jonglieren.'::text,'lernt'::text,'lernt'::text,'lernt'::text,'Er lernt gerade mit ihrer Hilfe zu jonglieren.'::text),
(303271,33697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він саме зараз ... жонглювати з її допомогою.'::text,'вчиться'::text,'вчиться'::text,'вчиться'::text,'Він саме зараз вчиться жонглювати з її допомогою.'::text),
(303270,33697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... a hacer malabares con su ayuda ahora mismo.'::text,'está aprendiendo'::text,'aprende'::text,'está aprendiendo'::text,'Él está aprendiendo a hacer malabares con su ayuda ahora mismo.'::text),
(303269,33697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à jongler avec son aide en ce moment.'::text,'est en train d''apprendre'::text,'apprend'::text,'est en train d''apprendre'::text,'Il est en train d''apprendre à jongler avec son aide en ce moment.'::text),
(303272,33697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an onun yardımıyla jonglörlük yapmayı ...'::text,'öğreniyor'::text,'öğrenir'::text,'öğreniyor'::text,'Şu an onun yardımıyla jonglörlük yapmayı öğreniyor.'::text),
(303273,33697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most épp ... zsonglőrködni a segítségével.'::text,'tanul'::text,'tanul'::text,'tanul'::text,'Most épp tanul zsonglőrködni a segítségével.'::text),
(303276,33698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Show ist am Freitag, also ... er schnell Jonglieren lernen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Alter, die Show ist am Freitag, also muss er schnell Jonglieren lernen.'::text),
(303280,33698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, шоу в п''ятницю, тож він ... швидко навчитися жонглювати.'::text,'має'::text,'мусить'::text,'мав би'::text,'Бро, шоу в п''ятницю, тож він має швидко навчитися жонглювати.'::text),
(303279,33698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el show es el viernes, así que ... aprender malabares rápido.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tío, el show es el viernes, así que tiene que aprender malabares rápido.'::text),
(303278,33698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le show est vendredi, donc il ... apprendre à jongler vite.'::text,'doit'::text,'doit'::text,'devrait'::text,'Frère, le show est vendredi, donc il doit apprendre à jongler vite.'::text),
(303281,33698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gösteri cuma, bu yüzden jonglörlüğü hızlıca ...'::text,'öğrenmek zorunda'::text,'öğrenmeli'::text,'öğrenmeli'::text,'Kanka, gösteri cuma, bu yüzden jonglörlüğü hızlıca öğrenmek zorunda.'::text),
(303282,33698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, pénteken van a show, úgyhogy gyorsan meg ... tanulnia zsonglőrködni.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, pénteken van a show, úgyhogy gyorsan meg kell tanulnia zsonglőrködni.'::text),
(303285,33699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ihm fallen die Bälle runter, also ... er von ihr lernen, echt jetzt.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Digga, ihm fallen die Bälle runter, also sollte er von ihr lernen, echt jetzt.'::text),
(303289,33699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, у нього падають м''ячі, тож він ... вчитися в неї, чесно.'::text,'мав би'::text,'мав би'::text,'буде'::text,'Чувак, у нього падають м''ячі, тож він мав би вчитися в неї, чесно.'::text),
(303288,33699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, se le caen las pelotas, así que ... aprender de ella, en serio.'::text,'debería'::text,'debería'::text,'deberá'::text,'Tío, se le caen las pelotas, así que debería aprender de ella, en serio.'::text),
(303287,33699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il fait tomber les balles, donc il ... apprendre d''elle, sérieux.'::text,'devrait'::text,'devrait'::text,'devra'::text,'Mec, il fait tomber les balles, donc il devrait apprendre d''elle, sérieux.'::text),
(303290,33699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, topları düşürüyor, bu yüzden ondan ..., cidden.'::text,'öğrenmeli'::text,'öğrenmeli'::text,'öğrenecek'::text,'Kanka, topları düşürüyor, bu yüzden ondan öğrenmeli, cidden.'::text),
(303291,33699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, elejti a labdákat, úgyhogy tőle ... tanulnia, komolyan.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Haver, elejti a labdákat, úgyhogy tőle kellene tanulnia, komolyan.'::text),
(316425,35159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... einen Koffer und den ganzen Pariser Gehweg. Ikonisch.'::text,'hast'::text,'hat'::text,'hast'::text,'Du hast einen Koffer und den ganzen Pariser Gehweg. Ikonisch.'::text),
(316429,35159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... валізу і весь паризький тротуар. Культово.'::text,'маєш'::text,'має'::text,'маєш'::text,'Ти маєш валізу і весь паризький тротуар. Культово.'::text),
(316428,35159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... una maleta y toda la acera de París. Icónico.'::text,'tienes'::text,'tiene'::text,'tienes'::text,'Tú tienes una maleta y toda la acera de París. Icónico.'::text),
(316427,35159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... une valise et tout le trottoir de Paris. Iconique.'::text,'as'::text,'a'::text,'as'::text,'Tu as une valise et tout le trottoir de Paris. Iconique.'::text),
(316430,35159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin bir bavulun ve bütün bir Paris kaldırımın ...; ikonik.'::text,'var'::text,'var'::text,'var'::text,'Senin bir bavulun ve bütün bir Paris kaldırımın var; ikonik.'::text),
(316431,35159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neked ... egy bőröndöd, és tiéd az egész párizsi járda. Ikonikus.'::text,'van'::text,'van'::text,'van'::text,'Neked van egy bőröndöd, és tiéd az egész párizsi járda. Ikonikus.'::text),
(316434,35160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du gehst auf dem Gehweg an ... vorbei wie ein Profi.'::text,'2 Männern'::text,'2 Männern'::text,'2 Männern'::text,'Ehrlich, du gehst auf dem Gehweg an 2 Männern vorbei wie ein Profi.'::text),
(316438,35160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти обходиш ... на тротуарі як профі.'::text,'2 чоловіків'::text,'2 чоловіків'::text,'2 чоловіків'::text,'Чесно, ти обходиш 2 чоловіків на тротуарі як профі.'::text),
(316437,35160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad, adelantas a ... en la acera como una profesional.'::text,'2 hombres'::text,'2 hombres'::text,'2 hombres'::text,'De verdad, adelantas a 2 hombres en la acera como una profesional.'::text),
(316436,35160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu dépasses ... sur le trottoir comme une pro.'::text,'2 hommes'::text,'2 hommes'::text,'2 hommes'::text,'Franchement, tu dépasses 2 hommes sur le trottoir comme une pro.'::text),
(316439,35160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası kaldırımda ... yanından profesyonel gibi geçiyorsun.'::text,'2 adamın'::text,'2 adamın'::text,'2 adamın'::text,'Açıkçası kaldırımda 2 adamın yanından profesyonel gibi geçiyorsun.'::text),
(316440,35160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, úgy haladsz el ... mellett a járdán, mint egy profi.'::text,'2 férfi'::text,'2 férfi'::text,'2 férfi'::text,'Őszintén, úgy haladsz el 2 férfi mellett a járdán, mint egy profi.'::text),
(316443,35161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist ... coolste Person auf diesem Gehweg.'::text,'die'::text,'eine'::text,'eine'::text,'Ehrlich, du bist die coolste Person auf diesem Gehweg.'::text),
(316447,35161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... найкрутіша людина на цьому тротуарі.'::text,''::text,NULL::text,NULL::text,'Чесно, ти найкрутіша людина на цьому тротуарі.'::text),
(316446,35161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad, eres ... persona más guay de esta acera.'::text,'la'::text,'una'::text,'una'::text,'De verdad, eres la persona más guay de esta acera.'::text),
(316445,35161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu es ... personne la plus cool de ce trottoir.'::text,'la'::text,'une'::text,'une'::text,'Franchement, tu es la personne la plus cool de ce trottoir.'::text),
(316448,35161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen bu kaldırımdaki ... en havalı kişisin.'::text,''::text,'bir'::text,'bir'::text,'Açıkçası sen bu kaldırımdaki en havalı kişisin.'::text),
(316449,35161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te vagy ... legmenőbb ember ezen a járdán.'::text,'a'::text,'egy'::text,'egy'::text,'Őszintén, te vagy a legmenőbb ember ezen a járdán.'::text),
(316452,35162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie steht auf ... Gehweg vor der Hoteltür.'::text,'diesem'::text,'diesen'::text,'jenen'::text,'Sie steht auf diesem Gehweg vor der Hoteltür.'::text),
(316456,35162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона стоїть на ... тротуарі біля дверей готелю.'::text,'цьому'::text,'цих'::text,'тих'::text,'Вона стоїть на цьому тротуарі біля дверей готелю.'::text),
(316455,35162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está de pie en ... acera junto a la puerta del hotel.'::text,'esta'::text,'estas'::text,'esas'::text,'Está de pie en esta acera junto a la puerta del hotel.'::text),
(316454,35162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se tient sur ... trottoir devant la porte de l''hôtel.'::text,'ce'::text,'ces'::text,'ces'::text,'Elle se tient sur ce trottoir devant la porte de l''hôtel.'::text),
(316457,35162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otel kapısının önündeki ... kaldırımda duruyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Otel kapısının önündeki bu kaldırımda duruyor.'::text),
(316458,35162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a járdán áll a hotel ajtaja előtt.'::text,'Ezen'::text,'Ezeken'::text,'Azokon'::text,'Ezen a járdán áll a hotel ajtaja előtt.'::text),
(316470,35164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie muss ... Gehweg stehen, die Autos direkt neben ihr.'::text,'auf dem'::text,'im'::text,'am'::text,'Alter, sie muss auf dem Gehweg stehen, die Autos direkt neben ihr.'::text),
(316474,35164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона має стояти ... тротуарі, машини просто поруч.'::text,'на'::text,'у'::text,'біля'::text,'Бро, вона має стояти на тротуарі, машини просто поруч.'::text),
(316473,35164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, tiene que estar ... la acera, con los coches justo al lado.'::text,'en'::text,'en'::text,'a'::text,'Tío, tiene que estar en la acera, con los coches justo al lado.'::text),
(316472,35164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle doit rester ... trottoir, les voitures juste à côté d''elle.'::text,'sur le'::text,'dans le'::text,'au'::text,'Frère, elle doit rester sur le trottoir, les voitures juste à côté d''elle.'::text),
(316475,35164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kaldırımın ... durmak zorunda, arabalar hemen yanında.'::text,'üstünde'::text,'içinde'::text,NULL::text,'Kanka, kaldırımın üstünde durmak zorunda, arabalar hemen yanında.'::text),
(316476,35164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a ... kell állnia, közvetlenül mellette az autók.'::text,'járdán'::text,'járdában'::text,'járdánál'::text,'Tesó, a járdán kell állnia, közvetlenül mellette az autók.'::text),
(316479,35165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gehweg-KPI: Sie geht ... Meter bis zur Tür.'::text,'zwanzig'::text,'zwanzigsten'::text,'Zwanziger'::text,'Gehweg-KPI: Sie geht zwanzig Meter bis zur Tür.'::text),
(316483,35165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI тротуару: вона проходить ... метрів до дверей.'::text,'двадцять'::text,'двадцятий'::text,'двадцятки'::text,'KPI тротуару: вона проходить двадцять метрів до дверей.'::text),
(316482,35165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI de acera: camina ... metros hasta la puerta.'::text,'veinte'::text,'vigésimo'::text,'veinte'::text,'KPI de acera: camina veinte metros hasta la puerta.'::text),
(316481,35165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI trottoir : elle marche ... mètres jusqu''à la porte.'::text,'vingt'::text,'vingtième'::text,'vingt'::text,'KPI trottoir : elle marche vingt mètres jusqu''à la porte.'::text),
(316484,35165,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaldırım KPI''ı: kapıya kadar ... metre yürüyor.'::text,'yirmi'::text,'yirminci'::text,'yirmiler'::text,'Kaldırım KPI''ı: kapıya kadar yirmi metre yürüyor.'::text),
(316485,35165,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Járda-KPI: ... métert sétál az ajtóig.'::text,'húsz'::text,'huszadik'::text,'huszasok'::text,'Járda-KPI: húsz métert sétál az ajtóig.'::text),
(299163,33241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hörst jeden Tag Musik, aber jetzt ... du mit geschlossenen Augen. Ikonisch.'::text,'lächelst'::text,'lächelst'::text,NULL::text,'Du hörst jeden Tag Musik, aber jetzt lächelst du mit geschlossenen Augen. Ikonisch.'::text),
(299167,33241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти щодня чуєш музику, але зараз ... із заплющеними очима. Культово.'::text,'усміхаєшся'::text,'усміхаєшся'::text,NULL::text,'Ти щодня чуєш музику, але зараз усміхаєшся із заплющеними очима. Культово.'::text),
(299166,33241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyes música a diario, pero ahora ... con los ojos cerrados. Icónico.'::text,'estás sonriendo'::text,'sonríes'::text,NULL::text,'Oyes música a diario, pero ahora estás sonriendo con los ojos cerrados. Icónico.'::text),
(299165,33241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu entends de la musique tous les jours, mais là tu ... les yeux fermés. Iconique.'::text,'es en train de sourire'::text,'souris'::text,NULL::text,'Tu entends de la musique tous les jours, mais là tu es en train de sourire les yeux fermés. Iconique.'::text),
(299168,33241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün müzik duyuyorsun ama şimdi gözlerin kapalı ...; ikonik.'::text,'gülümsüyorsun'::text,'gülümsersin'::text,NULL::text,'Her gün müzik duyuyorsun ama şimdi gözlerin kapalı gülümsüyorsun; ikonik.'::text),
(299169,33241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nap hallasz zenét, de most csukott szemmel ...; ikonikus.'::text,'mosolyogsz'::text,'mosolyogsz'::text,NULL::text,'Minden nap hallasz zenét, de most csukott szemmel mosolyogsz; ikonikus.'::text),
(299172,33242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Idee, echt. Der Mann an der Tür ... jedes Geheimnis hören.'::text,'wird'::text,'wird'::text,'wird'::text,'Tolle Idee, echt. Der Mann an der Tür wird jedes Geheimnis hören.'::text),
(299176,33242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова ідея, звісно. Чоловік біля дверей ... кожен секрет.'::text,'почує'::text,'почує'::text,'почує'::text,'Чудова ідея, звісно. Чоловік біля дверей почує кожен секрет.'::text),
(299175,33242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran idea, obviamente. El hombre de la puerta ... todos los secretos.'::text,'oirá'::text,'oirá'::text,'oirá'::text,'Gran idea, obviamente. El hombre de la puerta oirá todos los secretos.'::text),
(299174,33242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super idée, évidemment. L''homme à la porte ... chaque secret.'::text,'entendra'::text,'entendra'::text,'entendra'::text,'Super idée, évidemment. L''homme à la porte entendra chaque secret.'::text),
(299177,33242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika fikir, belli ki. Kapıdaki adam her sırrı ...'::text,'duyacak'::text,'duyacak'::text,'duyacak'::text,'Harika fikir, belli ki. Kapıdaki adam her sırrı duyacak.'::text),
(299178,33242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek ötlet, nyilván. Az ajtónál álló férfi minden titkot ...'::text,'meg fog hallani'::text,'meg fog hallani'::text,'meg fog hallani'::text,'Remek ötlet, nyilván. Az ajtónál álló férfi minden titkot meg fog hallani.'::text),
(299181,33243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekter Plan. Die Menge ... nach diesem Konzert nichts mehr hören.'::text,'wird'::text,'werden'::text,'wird'::text,'Perfekter Plan. Die Menge wird nach diesem Konzert nichts mehr hören.'::text),
(299185,33243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний план. Натовп після цього концерту нічого не ...'::text,'почує'::text,'почують'::text,'почує'::text,'Бездоганний план. Натовп після цього концерту нічого не почує.'::text),
(299184,33243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan perfecto. La multitud no ... nada después de este concierto.'::text,'va a oír'::text,'van a oír'::text,'va a oír'::text,'Plan perfecto. La multitud no va a oír nada después de este concierto.'::text),
(299183,33243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan parfait. La foule ne ... plus rien après ce concert.'::text,'va entendre'::text,'vont entendre'::text,'va entendre'::text,'Plan parfait. La foule ne va entendre plus rien après ce concert.'::text),
(299186,33243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz plan. Kalabalık bu konserden sonra hiçbir şey ...'::text,'duymayacak'::text,'duymayacaklar'::text,'duymayacak'::text,'Kusursuz plan. Kalabalık bu konserden sonra hiçbir şey duymayacak.'::text),
(299187,33243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan terv. A tömeg e koncert után semmit sem ... hallani.'::text,'fog'::text,'fognak'::text,'fog'::text,'Hibátlan terv. A tömeg e koncert után semmit sem fog hallani.'::text),
(299190,33244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Ohr ist an der Bürotür, also ... er etwas hören.'::text,'wird'::text,'wird'::text,NULL::text,'Sein Ohr ist an der Bürotür, also wird er etwas hören.'::text),
(299194,33244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його вухо на дверях офісу, тож він ... щось.'::text,'почує'::text,'почує'::text,NULL::text,'Його вухо на дверях офісу, тож він почує щось.'::text),
(299193,33244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene la oreja en la puerta de la oficina, así que ... algo.'::text,'va a oír'::text,'oirá'::text,NULL::text,'Tiene la oreja en la puerta de la oficina, así que va a oír algo.'::text),
(299192,33244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a l''oreille collée à la porte du bureau, donc il ... quelque chose.'::text,'va entendre'::text,'entendra'::text,NULL::text,'Il a l''oreille collée à la porte du bureau, donc il va entendre quelque chose.'::text),
(299195,33244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kulağı ofis kapısında, bu yüzden bir şey ...'::text,'duyacak'::text,'duyacak'::text,NULL::text,'Kulağı ofis kapısında, bu yüzden bir şey duyacak.'::text),
(299196,33244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A füle az iroda ajtaján van, úgyhogy ... valamit.'::text,'hallani fog'::text,'hallani fog'::text,NULL::text,'A füle az iroda ajtaján van, úgyhogy hallani fog valamit.'::text),
(299199,33245,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt den Song und beschließt, dass er ihn noch mal hören ...'::text,'muss'::text,'muss'::text,'sollte'::text,'Er liebt den Song und beschließt, dass er ihn noch mal hören muss.'::text),
(299203,33245,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обожнює пісню і вирішує, що ... почути її знову.'::text,'мусить'::text,'має'::text,'мав би'::text,'Він обожнює пісню і вирішує, що мусить почути її знову.'::text),
(299202,33245,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le encanta la canción y decide que ... oírla otra vez.'::text,'debe'::text,'tiene que'::text,'debería'::text,'Le encanta la canción y decide que debe oírla otra vez.'::text),
(299201,33245,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il adore la chanson et décide qu''il ... l''entendre encore.'::text,'doit'::text,'doit'::text,'devrait'::text,'Il adore la chanson et décide qu''il doit l''entendre encore.'::text),
(299204,33245,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şarkıya bayılıyor ve karar veriyor: onu tekrar ...'::text,'duymalı'::text,'duymak zorunda'::text,'duymalı'::text,'Şarkıya bayılıyor ve karar veriyor: onu tekrar duymalı.'::text),
(299205,33245,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádja a dalt, és elhatározza, hogy újra ... hallania.'::text,'kell'::text,'kell'::text,'kellene'::text,'Imádja a dalt, és elhatározza, hogy újra kell hallania.'::text),
(299208,33246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir gesagt, du ... diese Geschichte zuerst hören.'::text,'solltest'::text,'solltest'::text,'sollst'::text,'Mädel, sie hat mir gesagt, du solltest diese Geschichte zuerst hören.'::text),
