(314220,34914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qualitätsziel: Er will heute ... vom Olivenstand.'::text,'3 Proben'::text,'3 Probe'::text,'3 Proben'::text,'Qualitätsziel: Er will heute 3 Proben vom Olivenstand.'::text),
(314224,34914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мета якості: сьогодні він хоче ... з прилавка з оливками.'::text,'3 зразки'::text,'3 зразок'::text,'3 зразки'::text,'Мета якості: сьогодні він хоче 3 зразки з прилавка з оливками.'::text),
(314223,34914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo de calidad: hoy quiere ... del puesto de aceitunas.'::text,'3 muestras'::text,'3 muestra'::text,'3 muestras'::text,'Objetivo de calidad: hoy quiere 3 muestras del puesto de aceitunas.'::text),
(314222,34914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif qualité : il veut ... du stand d''olives aujourd''hui.'::text,'3 échantillons'::text,'3 échantillon'::text,'3 échantillons'::text,'Objectif qualité : il veut 3 échantillons du stand d''olives aujourd''hui.'::text),
(314225,34914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalite hedefi: bugün zeytin tezgâhından ... istiyor.'::text,'3 numune'::text,'3 numune'::text,'3 numuneler'::text,'Kalite hedefi: bugün zeytin tezgâhından 3 numune istiyor.'::text),
(314226,34914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minőségi cél: ma ... akar az olívástandtól.'::text,'3 mintát'::text,'3 mintát'::text,'3 mintát'::text,'Minőségi cél: ma 3 mintát akar az olívástandtól.'::text),
(314229,34915,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Olive ist ... kleine Probe, also isst er sie mit einem Bissen.'::text,'eine'::text,'die'::text,'eine'::text,'Eine Olive ist eine kleine Probe, also isst er sie mit einem Bissen.'::text),
(314233,34915,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна оливка — це ... маленький зразок, тож він з''їдає її за один укус.'::text,''::text,NULL::text,NULL::text,'Одна оливка — це маленький зразок, тож він з''їдає її за один укус.'::text),
(314232,34915,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una aceituna es ... muestra pequeña, así que se la come de un bocado.'::text,'una'::text,'la'::text,'una'::text,'Una aceituna es una muestra pequeña, así que se la come de un bocado.'::text),
(314231,34915,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une olive, c''est ... petit échantillon, alors il la mange en une bouchée.'::text,'un'::text,'le'::text,'un'::text,'Une olive, c''est un petit échantillon, alors il la mange en une bouchée.'::text),
(314234,34915,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir zeytin ... küçük numune, bu yüzden onu tek lokmada yiyor.'::text,'bir'::text,NULL::text,'bir'::text,'Bir zeytin bir küçük numune, bu yüzden onu tek lokmada yiyor.'::text),
(314235,34915,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy olajbogyó ... kis minta, ezért egy harapással megeszi.'::text,'egy'::text,'a'::text,'egy'::text,'Egy olajbogyó egy kis minta, ezért egy harapással megeszi.'::text),
(314238,34916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! ... Olivenprobe in meinem Mund ist die schlimmste überhaupt!'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Nein! Diese Olivenprobe in meinem Mund ist die schlimmste überhaupt!'::text),
(314242,34916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! ... оливковий зразок у моєму роті — найгірший у світі!'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Ні! Цей оливковий зразок у моєму роті — найгірший у світі!'::text),
(314241,34916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡... muestra de aceituna en mi boca es la peor de la historia!'::text,'Esta'::text,'Estas'::text,'Esas'::text,'¡No! ¡Esta muestra de aceituna en mi boca es la peor de la historia!'::text),
(314240,34916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! ... échantillon d''olive dans ma bouche est le pire de tous !'::text,'Cet'::text,'Ces'::text,'Ces'::text,'Non ! Cet échantillon d''olive dans ma bouche est le pire de tous !'::text),
(314243,34916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Ağzımdaki ... zeytin numunesi gelmiş geçmiş en kötüsü!'::text,'bu'::text,'bu'::text,'şu'::text,'Hayır! Ağzımdaki bu zeytin numunesi gelmiş geçmiş en kötüsü!'::text),
(314244,34916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! ... az olívaminta a számban a valaha volt legrosszabb!'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ne! Ez az olívaminta a számban a valaha volt legrosszabb!'::text),
(314247,34917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Er isst ... einzige Olivenprobe in einer Sekunde!'::text,'seine'::text,'ihre'::text,'ihre'::text,'Katastrophe! Er isst seine einzige Olivenprobe in einer Sekunde!'::text),
(314251,34917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Він з''їдає ... єдиний оливковий зразок за одну секунду!'::text,'свій'::text,'свій'::text,'свій'::text,'Катастрофа! Він з''їдає свій єдиний оливковий зразок за одну секунду!'::text),
(314250,34917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Se come ... única muestra de aceituna en un segundo!'::text,'su'::text,'su'::text,'su'::text,'¡Desastre! ¡Se come su única muestra de aceituna en un segundo!'::text),
(314249,34917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il mange ... seul échantillon d''olive en une seconde !'::text,'son'::text,'son'::text,'leur'::text,'Catastrophe ! Il mange son seul échantillon d''olive en une seconde !'::text),
(314252,34917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! ... tek zeytin numunesini bir saniyede yiyor!'::text,'Onun'::text,'Onun'::text,'Onların'::text,'Felaket! Onun tek zeytin numunesini bir saniyede yiyor!'::text),
(314253,34917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Egy másodperc alatt megeszi az egyetlen ...!'::text,'olívamintáját'::text,'olívamintáját'::text,'olívamintájukat'::text,'Katasztrófa! Egy másodperc alatt megeszi az egyetlen olívamintáját!'::text),
(314256,34918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist diese Olivenprobe so sauer? Das ist ein Albtraum!'::text,'Warum'::text,'Wer'::text,'Wo'::text,'Warum ist diese Olivenprobe so sauer? Das ist ein Albtraum!'::text),
(314260,34918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... цей оливковий зразок такий кислий? Це жах!'::text,'Чому'::text,'Хто'::text,'Де'::text,'Чому цей оливковий зразок такий кислий? Це жах!'::text),
(314259,34918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está tan ácida esta muestra de aceituna? ¡Es una pesadilla!'::text,'Por qué'::text,'Quién'::text,'Dónde'::text,'¿Por qué está tan ácida esta muestra de aceituna? ¡Es una pesadilla!'::text),
(314258,34918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cet échantillon d''olive est-il si acide ? C''est un cauchemar !'::text,'Pourquoi'::text,'Qui'::text,'Où'::text,'Pourquoi cet échantillon d''olive est-il si acide ? C''est un cauchemar !'::text),
(314261,34918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu zeytin numunesi ... bu kadar ekşi? Bu bir kâbus!'::text,'neden'::text,'kim'::text,'nerede'::text,'Bu zeytin numunesi neden bu kadar ekşi? Bu bir kâbus!'::text),
(314262,34918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ilyen savanyú ez az olívaminta? Ez egy rémálom!'::text,'Miért'::text,'Ki'::text,'Hol'::text,'Miért ilyen savanyú ez az olívaminta? Ez egy rémálom!'::text),
(314265,34919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er probiert ... Samstag auf dem Markt eine Olivenprobe.'::text,'am'::text,'im'::text,'um'::text,'Er probiert am Samstag auf dem Markt eine Olivenprobe.'::text),
(314269,34919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він куштує оливковий зразок на ринку ... суботу.'::text,'у'::text,'у'::text,'о'::text,'Він куштує оливковий зразок на ринку у суботу.'::text),
(314268,34919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prueba una muestra de aceituna en el mercado ... el sábado.'::text,''::text,'en'::text,'a'::text,'Prueba una muestra de aceituna en el mercado el sábado.'::text),
(314267,34919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il goûte un échantillon d''olive au marché ... samedi.'::text,''::text,'dans'::text,'à'::text,'Il goûte un échantillon d''olive au marché samedi.'::text),
(314270,34919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumartesi ... pazarda bir zeytin numunesi tadıyor.'::text,''::text,NULL::text,NULL::text,'Cumartesi pazarda bir zeytin numunesi tadıyor.'::text),
(314271,34919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... egy olívamintát kóstol a piacon.'::text,'Szombaton'::text,'Szombatban'::text,'Szombatkor'::text,'Szombaton egy olívamintát kóstol a piacon.'::text),
(304968,33886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Löffel ist voll. Klar, sie ... diese Medizin lieben.'::text,'wird'::text,'wird'::text,NULL::text,'Ihr Löffel ist voll. Klar, sie wird diese Medizin lieben.'::text),
(304972,33886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її ложка повна. Звісно, вона ... ці ліки.'::text,'полюбить'::text,'полюбить'::text,NULL::text,'Її ложка повна. Звісно, вона полюбить ці ліки.'::text),
(304971,33886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene la cuchara llena. Obviamente, esta medicina le ...'::text,'va a encantar'::text,'encantará'::text,NULL::text,'Tiene la cuchara llena. Obviamente, esta medicina le va a encantar.'::text),
(304970,33886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa cuillère est pleine. Évidemment, elle ... ce médicament.'::text,'va adorer'::text,'adorera'::text,NULL::text,'Sa cuillère est pleine. Évidemment, elle va adorer ce médicament.'::text),
(304973,33886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaşığı dolu. Belli ki bu ilaca ...'::text,'bayılacak'::text,'bayılacak'::text,NULL::text,'Kaşığı dolu. Belli ki bu ilaca bayılacak.'::text),
(304974,33886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tele a kanala. Nyilván ... ezt a gyógyszert.'::text,'imádni fogja'::text,'imádni fogja'::text,NULL::text,'Tele a kanala. Nyilván imádni fogja ezt a gyógyszert.'::text),
(304977,33887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Medizin ist ein Albtraum! Sie trinkt danach eine Menge ...!'::text,'Wasser'::text,'Wasser'::text,'ein Wasser'::text,'Diese Medizin ist ein Albtraum! Sie trinkt danach eine Menge Wasser!'::text),
(304981,33887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці ліки — жах! Після них вона п''є багато ...!'::text,'води'::text,'води'::text,'води'::text,'Ці ліки — жах! Після них вона п''є багато води!'::text),
(304980,33887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta medicina es una pesadilla! ¡Después bebe un montón de ...!'::text,'agua'::text,'agua'::text,'un agua'::text,'¡Esta medicina es una pesadilla! ¡Después bebe un montón de agua!'::text),
(304979,33887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce médicament est un cauchemar ! Elle boit beaucoup ... après !'::text,'d''eau'::text,'d''eau'::text,'d''une eau'::text,'Ce médicament est un cauchemar ! Elle boit beaucoup d''eau après !'::text),
(304982,33887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ilaç bir kâbus! Ondan sonra bolca ... içiyor!'::text,'su'::text,'sular'::text,'bir su'::text,'Bu ilaç bir kâbus! Ondan sonra bolca su içiyor!'::text),
(304983,33887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a gyógyszer egy rémálom! Utána rengeteg ... iszik!'::text,'vizet'::text,'vizet'::text,'egy vizet'::text,'Ez a gyógyszer egy rémálom! Utána rengeteg vizet iszik!'::text),
(304995,33889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... auf ihrem Tisch drei Sorten Medizin.'::text,'sind'::text,'ist'::text,'sein'::text,'Bestie, anscheinend sind auf ihrem Tisch drei Sorten Medizin.'::text),
(304999,33889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, на її столі ... три види ліків.'::text,'є'::text,'є'::text,'бути'::text,'Подружко, кажуть, на її столі є три види ліків.'::text),
(304998,33889,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ... tres tipos de medicina en su mesa.'::text,'hay'::text,'hay'::text,'hay'::text,'Amiga, al parecer hay tres tipos de medicina en su mesa.'::text),
(304997,33889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment ... trois sortes de médicaments sur sa table.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Ma belle, apparemment il y a trois sortes de médicaments sur sa table.'::text),
(305000,33889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya masasında üç çeşit ilaç ...'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, güya masasında üç çeşit ilaç var.'::text),
(305001,33889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag háromféle gyógyszer ... az asztalán.'::text,'van'::text,'van'::text,'lenni'::text,'Csajszi, állítólag háromféle gyógyszer van az asztalán.'::text),
(305004,33890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir erzählt, ihr Arzt sagt, sie ... diese Medizin nehmen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Mädel, sie hat mir erzählt, ihr Arzt sagt, sie muss diese Medizin nehmen.'::text),
(305008,33890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що її лікар каже, що вона ... приймати ці ліки.'::text,'має'::text,'мусить'::text,'мала б'::text,'Подруго, вона сказала мені, що її лікар каже, що вона має приймати ці ліки.'::text),
(305007,33890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que su médico dice que ... tomar esta medicina.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tía, me dijo que su médico dice que tiene que tomar esta medicina.'::text),
(305006,33890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit que son médecin dit qu''elle ... prendre ce médicament.'::text,'doit'::text,'doit'::text,'devrait'::text,'Ma belle, elle m''a dit que son médecin dit qu''elle doit prendre ce médicament.'::text),
(305009,33890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dedi ki doktoru bu ilacı ... diyormuş.'::text,'içmek zorunda'::text,'içmeli'::text,'içmeli'::text,'Kızım, bana dedi ki doktoru bu ilacı içmek zorunda diyormuş.'::text),
(305010,33890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy az orvosa szerint be ... vennie ezt a gyógyszert.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, azt mondta, hogy az orvosa szerint be kell vennie ezt a gyógyszert.'::text),
(305013,33891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Medizin schmeckt furchtbar, also ... du danach Wasser trinken, echt.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Alter, die Medizin schmeckt furchtbar, also solltest du danach Wasser trinken, echt.'::text),
(305017,33891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, ліки на смак жахливі, тож ти ... потім випити води, чесно.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Чувак, ліки на смак жахливі, тож ти мав би потім випити води, чесно.'::text),
(305016,33891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la medicina sabe fatal, así que ... beber agua después, en serio.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Tío, la medicina sabe fatal, así que deberías beber agua después, en serio.'::text),
(305015,33891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, le médicament a un goût horrible, donc tu ... boire de l''eau après, sérieux.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Mec, le médicament a un goût horrible, donc tu devrais boire de l''eau après, sérieux.'::text),
(305018,33891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ilacın tadı berbat, bu yüzden sonra su ..., cidden.'::text,'içmelisin'::text,'içeceksin'::text,'içmelisin'::text,'Kanka, ilacın tadı berbat, bu yüzden sonra su içmelisin, cidden.'::text),
(305019,33891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, borzalmas íze van a gyógyszernek, úgyhogy utána vizet ... innod, komolyan.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Haver, borzalmas íze van a gyógyszernek, úgyhogy utána vizet kellene innod, komolyan.'::text),
(305022,33892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Medizin schmeckt schlecht, ... trinkt sie ein Glas Wasser.'::text,'also'::text,'weil'::text,'aber'::text,'Die Medizin schmeckt schlecht, also trinkt sie ein Glas Wasser.'::text),
(305026,33892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ліки несмачні, ... вона п''є склянку води.'::text,'тому'::text,'бо'::text,'але'::text,'Ліки несмачні, тому вона п''є склянку води.'::text),
(305025,33892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La medicina sabe mal, ... ella bebe un vaso de agua.'::text,'así que'::text,'porque'::text,'pero'::text,'La medicina sabe mal, así que ella bebe un vaso de agua.'::text),
(305024,33892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le médicament a mauvais goût, ... elle boit un verre d''eau.'::text,'donc'::text,'parce que'::text,'mais'::text,'Le médicament a mauvais goût, donc elle boit un verre d''eau.'::text),
(305027,33892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlacın tadı kötü, ... bir bardak su içiyor.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'İlacın tadı kötü, bu yüzden bir bardak su içiyor.'::text),
(305028,33892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyógyszernek rossz az íze, ... megiszik egy pohár vizet.'::text,'ezért'::text,'mert'::text,'de'::text,'A gyógyszernek rossz az íze, ezért megiszik egy pohár vizet.'::text),
(301341,33483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... dich in einer Minute zwanzig Leuten vorstellen. Beeindruckend.'::text,'kannst'::text,'kannst'::text,'bist'::text,'Du kannst dich in einer Minute zwanzig Leuten vorstellen. Beeindruckend.'::text),
(301345,33483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... представитися двадцятьом людям за хвилину. Вражає.'::text,'можеш'::text,'можеш'::text,'є'::text,'Ти можеш представитися двадцятьом людям за хвилину. Вражає.'::text),
