(328444,36494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт о 17:00: саме зараз вона ... селфі у своїй жовтій сукні.'::text,'робить'::text,'робить'::text,'робить'::text,'Звіт о 17:00: саме зараз вона робить селфі у своїй жовтій сукні.'::text),
(328443,36494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe de las 17:00: ahora mismo ... un selfie con su vestido amarillo.'::text,'se está haciendo'::text,'se hace'::text,'se está haciendo'::text,'Informe de las 17:00: ahora mismo se está haciendo un selfie con su vestido amarillo.'::text),
(328442,36494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport de 17 h : en ce moment, elle ... un selfie dans sa robe jaune.'::text,'est en train de prendre'::text,'prend'::text,'est en train de prendre'::text,'Rapport de 17 h : en ce moment, elle est en train de prendre un selfie dans sa robe jaune.'::text),
(328445,36494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 17.00 raporu: şu an sarı elbisesiyle selfie ...'::text,'çekiyor'::text,'çeker'::text,'çekiyor'::text,'Saat 17.00 raporu: şu an sarı elbisesiyle selfie çekiyor.'::text),
(328446,36494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés 17 órakor: most épp ... egy szelfit a sárga ruhájában.'::text,'készít'::text,'készít'::text,'készít'::text,'Jelentés 17 órakor: most épp készít egy szelfit a sárga ruhájában.'::text),
(328449,36495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute ... sie Gelb, weil ihr Kleid gelb ist.'::text,'trägt'::text,'trägt'::text,NULL::text,'Heute trägt sie Gelb, weil ihr Kleid gelb ist.'::text),
(328453,36495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вона ... жовте, бо її сукня жовта.'::text,'носить'::text,'носить'::text,NULL::text,'Сьогодні вона носить жовте, бо її сукня жовта.'::text),
(328452,36495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... amarillo porque su vestido es amarillo.'::text,'está llevando'::text,'lleva'::text,NULL::text,'Hoy está llevando amarillo porque su vestido es amarillo.'::text),
(328451,36495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aujourd''hui, elle ... du jaune parce que sa robe est jaune.'::text,'est en train de porter'::text,'porte'::text,NULL::text,'Aujourd''hui, elle est en train de porter du jaune parce que sa robe est jaune.'::text),
(328454,36495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün sarı ..., çünkü elbisesi sarı.'::text,'giyiyor'::text,'giyer'::text,NULL::text,'Bugün sarı giyiyor, çünkü elbisesi sarı.'::text),
(328455,36495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma sárgát ..., mert a ruhája sárga.'::text,'visel'::text,'visel'::text,NULL::text,'Ma sárgát visel, mert a ruhája sárga.'::text),
(328458,36496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, dein gelbes Kleid ... morgen der beste Look sein.'::text,'wird'::text,'war'::text,'wird'::text,'Ehrlich gesagt, dein gelbes Kleid wird morgen der beste Look sein.'::text),
(328462,36496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твоя жовта сукня завтра ... найкращим луком.'::text,'буде'::text,'була'::text,'буде'::text,'Чесно, твоя жовта сукня завтра буде найкращим луком.'::text),
(328461,36496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, tu vestido amarillo ... el mejor look mañana.'::text,'será'::text,'fue'::text,'será'::text,'No te voy a mentir, tu vestido amarillo será el mejor look mañana.'::text),
(328460,36496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, ta robe jaune ... le meilleur look demain.'::text,'sera'::text,'était'::text,'sera'::text,'Sans mentir, ta robe jaune sera le meilleur look demain.'::text),
(328463,36496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sarı elbisen yarın en iyi görünüm ...'::text,'olacak'::text,'idi'::text,'olacak'::text,'Yalan yok, sarı elbisen yarın en iyi görünüm olacak.'::text),
(328464,36496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, a sárga ruhád holnap ... a legjobb szett.'::text,'lesz'::text,'volt'::text,'lesz'::text,'Nem hazudok, a sárga ruhád holnap lesz a legjobb szett.'::text),
(328467,36497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kluger Plan, ehrlich: Du ... heute Abend das gelbe Selfie posten.'::text,'wirst'::text,'wirst'::text,'wird'::text,'Kluger Plan, ehrlich: Du wirst heute Abend das gelbe Selfie posten.'::text),
(328471,36497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розумний план, чесно: ти ... запостити те жовте селфі сьогодні ввечері.'::text,'збираєшся'::text,'збираєшся'::text,'збирається'::text,'Розумний план, чесно: ти збираєшся запостити те жовте селфі сьогодні ввечері.'::text),
(328470,36497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan inteligente, la verdad: ... publicar ese selfie amarillo esta noche.'::text,'vas a'::text,'vas a'::text,'va a'::text,'Plan inteligente, la verdad: vas a publicar ese selfie amarillo esta noche.'::text),
(328469,36497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan malin, franchement : tu ... poster ce selfie jaune ce soir.'::text,'vas'::text,'vas'::text,'va'::text,'Plan malin, franchement : tu vas poster ce selfie jaune ce soir.'::text),
(328472,36497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akıllıca plan, açıkçası: o sarı selfie''yi bu akşam ...'::text,'paylaşacaksın'::text,'paylaşacaksın'::text,'paylaşacak'::text,'Akıllıca plan, açıkçası: o sarı selfie''yi bu akşam paylaşacaksın.'::text),
(328473,36497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okos terv, őszintén: ma este ki ... posztolni azt a sárga szelfit.'::text,'fogod'::text,'fogod'::text,'fogja'::text,'Okos terv, őszintén: ma este ki fogod posztolni azt a sárga szelfit.'::text),
(328476,36498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber dein gelbes Kleid ist ... als alles in diesem Laden.'::text,'leuchtender'::text,'leuchtender'::text,'am leuchtendsten'::text,'Okay, aber dein gelbes Kleid ist leuchtender als alles in diesem Laden.'::text),
(328480,36498,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але твоя жовта сукня ... за все в цьому магазині.'::text,'яскравіша'::text,'більш яскрава'::text,'найяскравіша'::text,'Окей, але твоя жовта сукня яскравіша за все в цьому магазині.'::text),
(328479,36498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero tu vestido amarillo es ... que todo lo de esta tienda.'::text,'más brillante'::text,'más brillante'::text,'el más brillante'::text,'Vale, pero tu vestido amarillo es más brillante que todo lo de esta tienda.'::text),
(328478,36498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, mais ta robe jaune est ... que tout dans cette boutique.'::text,'plus éclatante'::text,'plus éclatante'::text,'la plus éclatante'::text,'Ok, mais ta robe jaune est plus éclatante que tout dans cette boutique.'::text),
(328481,36498,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam ama sarı elbisen bu mağazadaki her şeyden ...'::text,'daha parlak'::text,'daha parlak'::text,'en parlak'::text,'Tamam ama sarı elbisen bu mağazadaki her şeyden daha parlak.'::text),
(328482,36498,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de a sárga ruhád ... mindennél ebben a boltban.'::text,'élénkebb'::text,'élénkebb'::text,'legélénkebb'::text,'Oké, de a sárga ruhád élénkebb mindennél ebben a boltban.'::text),
(311142,34572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das lila Kleid, also ist das lila Kleid an ihr.'::text,'trägt'::text,'tragen'::text,'tragend'::text,'Sie trägt das lila Kleid, also ist das lila Kleid an ihr.'::text),
(311146,34572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... фіолетову сукню, тож фіолетова сукня на ній.'::text,'носить'::text,'носити'::text,'носячи'::text,'Вона носить фіолетову сукню, тож фіолетова сукня на ній.'::text),
(311145,34572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el vestido morado, así que el vestido morado lo tiene puesto.'::text,'lleva'::text,'llevar'::text,'llevando'::text,'Ella lleva el vestido morado, así que el vestido morado lo tiene puesto.'::text),
(311144,34572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la robe violette, donc la robe violette est sur elle.'::text,'porte'::text,'porter'::text,'portant'::text,'Elle porte la robe violette, donc la robe violette est sur elle.'::text),
(311147,34572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mor elbiseyi ..., yani mor elbise onun üstünde.'::text,'giyer'::text,'giymek'::text,'giyerek'::text,'Mor elbiseyi giyer, yani mor elbise onun üstünde.'::text),
(311148,34572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a lila ruhát, tehát a lila ruha rajta van.'::text,'viseli'::text,'viselni'::text,'viselő'::text,'Ő viseli a lila ruhát, tehát a lila ruha rajta van.'::text),
(311151,34573,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ich Lila tragen wie sie? Niemals! Das ist der schlimmste Tag!'::text,'Kann'::text,'Bin'::text,NULL::text,'Kann ich Lila tragen wie sie? Niemals! Das ist der schlimmste Tag!'::text),
(311155,34573,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чи ... я носити фіолетове, як вона? Ніколи! Це найгірший день!'::text,'можу'::text,'є'::text,NULL::text,'Чи можу я носити фіолетове, як вона? Ніколи! Це найгірший день!'::text),
(311154,34573,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... llevar morado como ella? ¡Nunca! ¡Es el peor día!'::text,'Puedo'::text,'Estoy'::text,NULL::text,'¿Puedo llevar morado como ella? ¡Nunca! ¡Es el peor día!'::text),
(311153,34573,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Est-ce que je ... porter du violet comme elle ? Jamais ! C''est le pire jour !'::text,'peux'::text,'suis'::text,NULL::text,'Est-ce que je peux porter du violet comme elle ? Jamais ! C''est le pire jour !'::text),
(311156,34573,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun gibi mor ... miyim? Asla! Bu en kötü gün!'::text,'giyebilir'::text,NULL::text,NULL::text,'Onun gibi mor giyebilir miyim? Asla! Bu en kötü gün!'::text),
(311157,34573,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... lilát, mint ő? Soha! Ez a legrosszabb nap!'::text,'Hordhatok'::text,'Vagyok'::text,NULL::text,'Hordhatok lilát, mint ő? Soha! Ez a legrosszabb nap!'::text),
(311160,34574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr lila Kleid ist ... als sein silberner Ring! Er ist am Boden zerstört!'::text,'hübscher'::text,'hübscher'::text,'am hübschesten'::text,'Ihr lila Kleid ist hübscher als sein silberner Ring! Er ist am Boden zerstört!'::text),
(311164,34574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її фіолетова сукня ... за його срібний перстень! Він розчавлений!'::text,'гарніша'::text,'більш гарна'::text,'найгарніша'::text,'Її фіолетова сукня гарніша за його срібний перстень! Він розчавлений!'::text),
(311163,34574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su vestido morado es ... que su anillo de plata! ¡Está destrozado!'::text,'más bonito'::text,'más bonito'::text,'el más bonito'::text,'¡Su vestido morado es más bonito que su anillo de plata! ¡Está destrozado!'::text),
(311162,34574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa robe violette est ... que sa bague en argent ! Il est anéanti !'::text,'plus jolie'::text,'plus jolie'::text,'la plus jolie'::text,'Sa robe violette est plus jolie que sa bague en argent ! Il est anéanti !'::text),
(311165,34574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun mor elbisesi onun gümüş yüzüğünden ...! Yıkıldı!'::text,'daha güzel'::text,'daha güzel'::text,'en güzel'::text,'Onun mor elbisesi onun gümüş yüzüğünden daha güzel! Yıkıldı!'::text),
(311166,34574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lila ruhája ... az ő ezüstgyűrűjénél! Teljesen össze van törve!'::text,'szebb'::text,'szebb'::text,'legszebb'::text,'A lila ruhája szebb az ő ezüstgyűrűjénél! Teljesen össze van törve!'::text),
(311178,34576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, sie ... jetzt auf jeder Party Lila tragen.'::text,'sollte'::text,'soll'::text,'sollte'::text,'Hör mal, ich hab gehört, sie sollte jetzt auf jeder Party Lila tragen.'::text),
(311182,34576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вона ... тепер носити фіолетове на кожну вечірку.'::text,'мала б'::text,'буде'::text,'мала б'::text,'Слухай, я чула, що вона мала б тепер носити фіолетове на кожну вечірку.'::text),
(311181,34576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que ... llevar morado a todas las fiestas a partir de ahora.'::text,'debería'::text,'deberá'::text,'debería'::text,'Oye, he oído que debería llevar morado a todas las fiestas a partir de ahora.'::text),
(311180,34576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît qu''elle ... porter du violet à chaque soirée maintenant.'::text,'devrait'::text,'devra'::text,'devrait'::text,'Écoute, il paraît qu''elle devrait porter du violet à chaque soirée maintenant.'::text),
(311183,34576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki artık her partiye mor ...'::text,'giymeli'::text,'giyecek'::text,'giymeli'::text,'Dinle, duydum ki artık her partiye mor giymeli.'::text),
(311184,34576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy mostantól minden buliba lilát ... hordania.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Figyelj, azt hallottam, hogy mostantól minden buliba lilát kellene hordania.'::text),
(311187,34577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat in dem lila Kleid anscheinend so ... gelacht.'::text,'fröhlich'::text,'fröhlich'::text,'fröhlich'::text,'Rate mal, sie hat in dem lila Kleid anscheinend so fröhlich gelacht.'::text),
(311191,34577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона, кажуть, так ... сміялася в тій фіолетовій сукні.'::text,'щасливо'::text,'щасливий'::text,'щасливо'::text,'Уяви, вона, кажуть, так щасливо сміялася в тій фіолетовій сукні.'::text),
(311190,34577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, al parecer se rio tan ... con ese vestido morado.'::text,'felizmente'::text,'feliz'::text,'felizmente'::text,'Adivina, al parecer se rio tan felizmente con ese vestido morado.'::text),
(311189,34577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a ri si ... dans cette robe violette, apparemment.'::text,'joyeusement'::text,'joyeux'::text,'joyeusement'::text,'Devine quoi, elle a ri si joyeusement dans cette robe violette, apparemment.'::text),
(311192,34577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, güya o mor elbiseyle çok ... gülmüş.'::text,'mutlu bir şekilde'::text,'mutlu'::text,'mutlu bir şekilde'::text,'Bil bakalım, güya o mor elbiseyle çok mutlu bir şekilde gülmüş.'::text),
(311193,34577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag olyan ... nevetett abban a lila ruhában.'::text,'boldogan'::text,'boldog'::text,'boldogan'::text,'Képzeld, állítólag olyan boldogan nevetett abban a lila ruhában.'::text),
(311196,34578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das lila Kleid passt gut, ... lacht sie in den Spiegel.'::text,'also'::text,'weil'::text,'aber'::text,'Das lila Kleid passt gut, also lacht sie in den Spiegel.'::text),
(311200,34578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фіолетова сукня добре сидить, ... вона сміється до дзеркала.'::text,'тому'::text,'бо'::text,'але'::text,'Фіолетова сукня добре сидить, тому вона сміється до дзеркала.'::text),
(311199,34578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestido morado le queda bien, ... se ríe frente al espejo.'::text,'así que'::text,'porque'::text,'pero'::text,'El vestido morado le queda bien, así que se ríe frente al espejo.'::text),
(311198,34578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La robe violette lui va bien, ... elle rit devant le miroir.'::text,'donc'::text,'parce que'::text,'mais'::text,'La robe violette lui va bien, donc elle rit devant le miroir.'::text),
(311201,34578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mor elbise iyi oturuyor, ... aynaya gülüyor.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Mor elbise iyi oturuyor, bu yüzden aynaya gülüyor.'::text),
(311202,34578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lila ruha jól áll, ... nevet a tükörbe.'::text,'ezért'::text,'mert'::text,'de'::text,'A lila ruha jól áll, ezért nevet a tükörbe.'::text),
(298371,33153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du ... heute eine richtig coole Frisur.'::text,'hast'::text,'hat'::text,'hast'::text,'Ganz ehrlich, du hast heute eine richtig coole Frisur.'::text),
(298375,33153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, ти ... сьогодні дуже круту зачіску.'::text,'маєш'::text,'має'::text,'маєш'::text,'Між нами, ти маєш сьогодні дуже круту зачіску.'::text),
(298374,33153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sin exagerar, hoy ... un peinado muy guay.'::text,'tienes'::text,'tiene'::text,'tienes'::text,'Sin exagerar, hoy tienes un peinado muy guay.'::text),
(298373,33153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Discrètement, tu ... une coiffure vraiment cool aujourd''hui.'::text,'as'::text,'a'::text,'as'::text,'Discrètement, tu as une coiffure vraiment cool aujourd''hui.'::text),
(298376,33153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, bugün gerçekten havalı bir saç modelin ...'::text,'var'::text,'var'::text,'var'::text,'Aramızda kalsın, bugün gerçekten havalı bir saç modelin var.'::text),
(298377,33153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak úgy mondom, ma nagyon menő frizurád ...'::text,'van'::text,'van'::text,'van'::text,'Csak úgy mondom, ma nagyon menő frizurád van.'::text),
(298380,33154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei perfekte ... in deiner Frisur? Respekt.'::text,'Dutts'::text,'Dutt'::text,'Dutts'::text,'Zwei perfekte Dutts in deiner Frisur? Respekt.'::text),
(298384,33154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві ідеальні ... у твоїй зачісці? Респект.'::text,'гульки'::text,'гулька'::text,'гульки'::text,'Дві ідеальні гульки у твоїй зачісці? Респект.'::text),
(298383,33154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Dos ... perfectos en tu peinado? Respeto.'::text,'moños'::text,'moño'::text,'moños'::text,'¿Dos moños perfectos en tu peinado? Respeto.'::text),
(298382,33154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux ... parfaits dans ta coiffure ? Respect.'::text,'chignons'::text,'chignon'::text,'chignons'::text,'Deux chignons parfaits dans ta coiffure ? Respect.'::text),
(298385,33154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saç modelinde iki mükemmel ...? Saygılar.'::text,'topuz'::text,'topuz'::text,'topuzlar'::text,'Saç modelinde iki mükemmel topuz? Saygılar.'::text),
(298386,33154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két tökéletes ... a frizurádban? Respekt.'::text,'konty'::text,'konty'::text,'konty'::text,'Két tökéletes konty a frizurádban? Respekt.'::text),
(298389,33155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber du hast ... neue Frisur, und die Frisur ist ikonisch.'::text,'eine'::text,'eine'::text,'die'::text,'Okay, aber du hast eine neue Frisur, und die Frisur ist ikonisch.'::text),
(298393,33155,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але в тебе ... нова зачіска, і ця зачіска культова.'::text,''::text,NULL::text,NULL::text,'Окей, але в тебе нова зачіска, і ця зачіска культова.'::text),
(298392,33155,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero tienes ... peinado nuevo, y el peinado es icónico.'::text,'un'::text,'un'::text,'el'::text,'Vale, pero tienes un peinado nuevo, y el peinado es icónico.'::text),
(298391,33155,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, mais tu as ... nouvelle coiffure, et la coiffure est iconique.'::text,'une'::text,'une'::text,'la'::text,'Ok, mais tu as une nouvelle coiffure, et la coiffure est iconique.'::text),
(298394,33155,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam ama ... yeni saç modelin var ve o saç modeli ikonik.'::text,'bir'::text,'bir'::text,NULL::text,'Tamam ama bir yeni saç modelin var ve o saç modeli ikonik.'::text),
(298395,33155,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de ... új frizurád van, és a frizura ikonikus.'::text,'egy'::text,'egy'::text,'az'::text,'Oké, de egy új frizurád van, és a frizura ikonikus.'::text),
(298407,33157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie streicht ... Haare glatt und macht eine neue Frisur.'::text,'ihre'::text,'seine'::text,'seine'::text,'Sie streicht ihre Haare glatt und macht eine neue Frisur.'::text),
(298411,33157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона пригладжує ... волосся і робить нову зачіску.'::text,'своє'::text,'своє'::text,'своє'::text,'Вона пригладжує своє волосся і робить нову зачіску.'::text),
(298410,33157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se alisa ... pelo y se hace un peinado nuevo.'::text,'su'::text,'su'::text,'su'::text,'Se alisa su pelo y se hace un peinado nuevo.'::text),
(298409,33157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle lisse ... cheveux et se fait une nouvelle coiffure.'::text,'ses'::text,'ses'::text,'ses'::text,'Elle lisse ses cheveux et se fait une nouvelle coiffure.'::text),
(298412,33157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... saçını düzeltip yeni bir saç modeli yapıyor.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Onun saçını düzeltip yeni bir saç modeli yapıyor.'::text),
(298413,33157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lesimítja a ..., és új frizurát csinál.'::text,'haját'::text,'haját'::text,'haját'::text,'Lesimítja a haját, és új frizurát csinál.'::text),
(298416,33158,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellos: Für diese riesige Frisur brauchte es nur ein bisschen ...'::text,'Zeit'::text,'Zeit'::text,'eine Zeit'::text,'Makellos: Für diese riesige Frisur brauchte es nur ein bisschen Zeit.'::text),
(298420,33158,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганно: ця величезна зачіска забрала лише трохи ...'::text,'часу'::text,'часу'::text,'часу'::text,'Бездоганно: ця величезна зачіска забрала лише трохи часу.'::text),
(298419,33158,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impecable: este peinado enorme solo llevó un poco de ...'::text,'tiempo'::text,'tiempo'::text,'un tiempo'::text,'Impecable: este peinado enorme solo llevó un poco de tiempo.'::text),
(298418,33158,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parfait : cette énorme coiffure n''a pris qu''un peu de ...'::text,'temps'::text,'temps'::text,'un temps'::text,'Parfait : cette énorme coiffure n''a pris qu''un peu de temps.'::text),
(298421,33158,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz: bu devasa saç modeli için sadece biraz ... gerekti.'::text,'zaman'::text,'zamanlar'::text,'bir zaman'::text,'Kusursuz: bu devasa saç modeli için sadece biraz zaman gerekti.'::text),
(298422,33158,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan: ez a hatalmas frizura csak egy kis ... vett igénybe.'::text,'időt'::text,'időt'::text,'egy időt'::text,'Hibátlan: ez a hatalmas frizura csak egy kis időt vett igénybe.'::text),
(298434,33160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In ihrer neuen Frisur ... zwei große Dutts.'::text,'sind'::text,'ist'::text,'sein'::text,'In ihrer neuen Frisur sind zwei große Dutts.'::text),
(298438,33160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У її новій зачісці ... дві великі гульки.'::text,'є'::text,'є'::text,'бути'::text,'У її новій зачісці є дві великі гульки.'::text),
(298437,33160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dos moños grandes en su peinado nuevo.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay dos moños grandes en su peinado nuevo.'::text),
(298436,33160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... deux gros chignons dans sa nouvelle coiffure.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a deux gros chignons dans sa nouvelle coiffure.'::text),
(298439,33160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni saç modelinde iki büyük topuz ...'::text,'var'::text,'var'::text,'olmak'::text,'Yeni saç modelinde iki büyük topuz var.'::text),
(298440,33160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az új frizurájában két nagy konty ...'::text,'van'::text,'van'::text,'lenni'::text,'Az új frizurájában két nagy konty van.'::text),
(297462,33052,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das lange Kleid des Models ... grün.'::text,'ist'::text,'sind'::text,'bin'::text,'Das lange Kleid des Models ist grün.'::text),
(297466,33052,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Довга сукня моделі ... зелена.'::text,'є'::text,'є'::text,'є'::text,'Довга сукня моделі є зелена.'::text),
(297465,33052,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestido largo de la modelo ... verde.'::text,'es'::text,'son'::text,'soy'::text,'El vestido largo de la modelo es verde.'::text),
(297464,33052,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La longue robe du mannequin ... verte.'::text,'est'::text,'sont'::text,'suis'::text,'La longue robe du mannequin est verte.'::text),
(297467,33052,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Modelin uzun elbisesi yeşil ...'::text,''::text,NULL::text,NULL::text,'Modelin uzun elbisesi yeşil.'::text),
(297468,33052,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell hosszú ruhája ... zöld.'::text,''::text,NULL::text,'vagyok'::text,'A modell hosszú ruhája zöld.'::text),
(297480,33054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... dieses grüne Kleid auf dem Laufsteg wie ein Star. Ikonisch.'::text,'trugst'::text,'trugst'::text,'trägst'::text,'Du trugst dieses grüne Kleid auf dem Laufsteg wie ein Star. Ikonisch.'::text),
(297484,33054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... ту зелену сукню на подіумі як зірка. Культово.'::text,'носила'::text,'носила'::text,'носиш'::text,'Ти носила ту зелену сукню на подіумі як зірка. Культово.'::text),
(297483,33054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ese vestido verde por la pasarela como una estrella. Icónico.'::text,'Llevaste'::text,'Llevaste'::text,'Llevas'::text,'Llevaste ese vestido verde por la pasarela como una estrella. Icónico.'::text),
(297482,33054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... cette robe verte sur le podium comme une star. Iconique.'::text,'as porté'::text,'as porté'::text,'portes'::text,'Tu as porté cette robe verte sur le podium comme une star. Iconique.'::text),
(297485,33054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yeşil elbiseyi podyumda bir yıldız gibi ...; ikonik.'::text,'giydin'::text,'giydin'::text,'giyersin'::text,'O yeşil elbiseyi podyumda bir yıldız gibi giydin; ikonik.'::text),
(297486,33054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy ... azt a zöld ruhát a kifutón, mint egy sztár. Ikonikus.'::text,'viselted'::text,'viselted'::text,'viseled'::text,'Úgy viselted azt a zöld ruhát a kifutón, mint egy sztár. Ikonikus.'::text),
(297489,33055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du trägst sonst Schwarz, aber gestern ... du Grün. Ehrlich, ikonisch.'::text,'trugst'::text,'trägst'::text,NULL::text,'Du trägst sonst Schwarz, aber gestern trugst du Grün. Ehrlich, ikonisch.'::text),
(297493,33055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зазвичай носиш чорне, але вчора ... зелене. Чесно, культово.'::text,'носила'::text,'носиш'::text,NULL::text,'Ти зазвичай носиш чорне, але вчора носила зелене. Чесно, культово.'::text),
(297492,33055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente llevas negro, pero ayer ... verde. Sinceramente, icónico.'::text,'llevaste'::text,'llevas'::text,NULL::text,'Normalmente llevas negro, pero ayer llevaste verde. Sinceramente, icónico.'::text),
(297491,33055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu portes du noir, mais hier tu ... du vert. Franchement, iconique.'::text,'as porté'::text,'portes'::text,NULL::text,'D''habitude tu portes du noir, mais hier tu as porté du vert. Franchement, iconique.'::text),
(297494,33055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde siyah giyersin ama dün yeşil ...; açıkçası ikonik.'::text,'giydin'::text,'giyersin'::text,NULL::text,'Genelde siyah giyersin ama dün yeşil giydin; açıkçası ikonik.'::text),
(297495,33055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában feketét hordasz, de tegnap zöldet ...; őszintén, ikonikus.'::text,'viseltél'::text,'viselsz'::text,NULL::text,'Általában feketét hordasz, de tegnap zöldet viseltél; őszintén, ikonikus.'::text),
(297498,33056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Model ... in einem grünen Kleid über den Laufsteg.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Das Model läuft in einem grünen Kleid über den Laufsteg.'::text),
(297502,33056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Модель ... подіумом у зеленій сукні.'::text,'іде'::text,'іде'::text,'іде'::text,'Модель іде подіумом у зеленій сукні.'::text),
(297501,33056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La modelo ... por la pasarela con un vestido verde.'::text,'está caminando'::text,'camina'::text,'está caminando'::text,'La modelo está caminando por la pasarela con un vestido verde.'::text),
(297500,33056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mannequin ... sur le podium dans une robe verte.'::text,'est en train de défiler'::text,'défile'::text,'est en train de défiler'::text,'Le mannequin est en train de défiler sur le podium dans une robe verte.'::text),
(297503,33056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Model yeşil bir elbiseyle podyumda ...'::text,'yürüyor'::text,'yürür'::text,'yürüyor'::text,'Model yeşil bir elbiseyle podyumda yürüyor.'::text),
(297504,33056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell egy zöld ruhában ... végig a kifutón.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'A modell egy zöld ruhában sétál végig a kifutón.'::text),
(297516,33058,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr grünes Kleid ist ... als alle anderen! Die sind erledigt!'::text,'länger'::text,'länger'::text,'am längsten'::text,'Ihr grünes Kleid ist länger als alle anderen! Die sind erledigt!'::text),
(297520,33058,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її зелена сукня ... за всі інші! Вони розчавлені!'::text,'довша'::text,'більш довга'::text,'найдовша'::text,'Її зелена сукня довша за всі інші! Вони розчавлені!'::text),
(297519,33058,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su vestido verde es ... que todos los demás! ¡Están destrozadas!'::text,'más largo'::text,'más largo'::text,'el más largo'::text,'¡Su vestido verde es más largo que todos los demás! ¡Están destrozadas!'::text),
(297518,33058,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa robe verte est ... que toutes les autres ! Elles sont anéanties !'::text,'plus longue'::text,'plus longue'::text,'la plus longue'::text,'Sa robe verte est plus longue que toutes les autres ! Elles sont anéanties !'::text),
(297521,33058,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun yeşil elbisesi diğer hepsinden ...! Yıkıldılar!'::text,'daha uzun'::text,'daha uzun'::text,'en uzun'::text,'Onun yeşil elbisesi diğer hepsinden daha uzun! Yıkıldılar!'::text),
(297522,33058,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zöld ruhája ... az összes többinél! Teljesen össze vannak törve!'::text,'hosszabb'::text,'hosszabb'::text,'leghosszabb'::text,'A zöld ruhája hosszabb az összes többinél! Teljesen össze vannak törve!'::text),
(297525,33059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, sie ist in dem grünen Kleid echt ... gelaufen.'::text,'langsam'::text,'langsam'::text,'langsam'::text,'Okay, also ich hab gehört, sie ist in dem grünen Kleid echt langsam gelaufen.'::text),
(297529,33059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що вона йшла в тій зеленій сукні дуже ...'::text,'повільно'::text,'повільний'::text,'повільно'::text,'Коротше, я чула, що вона йшла в тій зеленій сукні дуже повільно.'::text),
(297528,33059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues he oído que caminó muy ... con ese vestido verde.'::text,'lentamente'::text,'lento'::text,'lentamente'::text,'Vale, pues he oído que caminó muy lentamente con ese vestido verde.'::text),
(297527,33059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire qu''elle a marché vraiment ... dans cette robe verte.'::text,'lentement'::text,'lent'::text,'lentement'::text,'Bon, j''ai entendu dire qu''elle a marché vraiment lentement dans cette robe verte.'::text),
(297530,33059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duydum ki o yeşil elbiseyle çok ... yürümüş.'::text,'yavaşça'::text,'yavaş'::text,'yavaşça'::text,'Neyse, duydum ki o yeşil elbiseyle çok yavaşça yürümüş.'::text),
(297531,33059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt hallottam, hogy nagyon ... sétált abban a zöld ruhában.'::text,'lassan'::text,'lassú'::text,'lassan'::text,'Szóval, azt hallottam, hogy nagyon lassan sétált abban a zöld ruhában.'::text),
(319350,35484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Tag ... Tauben auf dieser armen Statue! Eine totale Katastrophe!'::text,'landen'::text,'landet'::text,'landend'::text,'Jeden Tag landen Tauben auf dieser armen Statue! Eine totale Katastrophe!'::text),
(319354,35484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щодня голуби ... на цій бідній статуї! Повна катастрофа!'::text,'сідають'::text,'сідає'::text,'сідаючи'::text,'Щодня голуби сідають на цій бідній статуї! Повна катастрофа!'::text),
(319353,35484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Todos los días las palomas ... sobre esta pobre estatua! ¡Un desastre total!'::text,'se posan'::text,'se posa'::text,'posándose'::text,'¡Todos los días las palomas se posan sobre esta pobre estatua! ¡Un desastre total!'::text),
(319352,35484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tous les jours, des pigeons ... sur cette pauvre statue ! Une catastrophe totale !'::text,'se posent'::text,'se pose'::text,'se posant'::text,'Tous les jours, des pigeons se posent sur cette pauvre statue ! Une catastrophe totale !'::text),
(319355,35484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün güvercinler bu zavallı heykelin üstüne ...! Tam bir felaket!'::text,'konarlar'::text,'konar'::text,'konarak'::text,'Her gün güvercinler bu zavallı heykelin üstüne konarlar! Tam bir felaket!'::text),
(319356,35484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nap galambok ... erre a szegény szoborra! Totális katasztrófa!'::text,'szállnak'::text,'száll'::text,'szálló'::text,'Minden nap galambok szállnak erre a szegény szoborra! Totális katasztrófa!'::text),
(319359,35485,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend hat sie einen Plan: Sie ... mit jeder Statue ein Selfie machen.'::text,'wird'::text,'wird'::text,NULL::text,'Bestie, anscheinend hat sie einen Plan: Sie wird mit jeder Statue ein Selfie machen.'::text),
(319363,35485,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, у неї є план: вона ... селфі з кожною статуєю.'::text,'збирається зробити'::text,'зробить'::text,NULL::text,'Подружко, кажуть, у неї є план: вона збирається зробити селфі з кожною статуєю.'::text),
(319362,35485,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer tiene un plan: ... un selfie con cada estatua.'::text,'se va a hacer'::text,'se hará'::text,NULL::text,'Amiga, al parecer tiene un plan: se va a hacer un selfie con cada estatua.'::text),
(319361,35485,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment elle a un plan : elle ... un selfie avec chaque statue.'::text,'va prendre'::text,'prendra'::text,NULL::text,'Ma belle, apparemment elle a un plan : elle va prendre un selfie avec chaque statue.'::text),
(319364,35485,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya bir planı var: her heykelle selfie ...'::text,'çekecek'::text,'çekecek'::text,NULL::text,'Kanka, güya bir planı var: her heykelle selfie çekecek.'::text),
(319365,35485,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag van egy terve: minden szoborral ... egy szelfit.'::text,'készíteni fog'::text,'készíteni fog'::text,NULL::text,'Csajszi, állítólag van egy terve: minden szoborral készíteni fog egy szelfit.'::text),
(319368,35486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sieht auf ihrem Spaziergang durch die Stadt ... Statuen.'::text,'viele'::text,'viel'::text,'eine Menge'::text,'Sie sieht auf ihrem Spaziergang durch die Stadt viele Statuen.'::text),
(319372,35486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона бачить ... статуй під час прогулянки містом.'::text,'багато'::text,'багато'::text,'багато'::text,'Вона бачить багато статуй під час прогулянки містом.'::text),
(319371,35486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ve ... estatuas en su paseo por la ciudad.'::text,'muchas'::text,'mucha'::text,'un montón de'::text,'Ve muchas estatuas en su paseo por la ciudad.'::text),
(319370,35486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle voit ... statues pendant sa balade en ville.'::text,'beaucoup de'::text,'beaucoup de'::text,'plein de'::text,'Elle voit beaucoup de statues pendant sa balade en ville.'::text),
(319373,35486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehir gezisinde ... heykel görüyor.'::text,'çok'::text,'çok'::text,'çok'::text,'Şehir gezisinde çok heykel görüyor.'::text),
(319374,35486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A városi sétáján ... szobrot lát.'::text,'sok'::text,'sok'::text,'rengeteg'::text,'A városi sétáján sok szobrot lát.'::text),
(319377,35487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf ihrer Stadttour ... drei verschiedene Statuen.'::text,'sind'::text,'ist'::text,'sein'::text,'Auf ihrer Stadttour sind drei verschiedene Statuen.'::text),
(319381,35487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На її екскурсії містом ... три різні статуї.'::text,'є'::text,'є'::text,'бути'::text,'На її екскурсії містом є три різні статуї.'::text),
(319380,35487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tres estatuas diferentes en su recorrido por la ciudad.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay tres estatuas diferentes en su recorrido por la ciudad.'::text),
(319379,35487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trois statues différentes sur son circuit en ville.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a trois statues différentes sur son circuit en ville.'::text),
(319382,35487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehir turunda üç farklı heykel ...'::text,'var'::text,'var'::text,'olmak'::text,'Şehir turunda üç farklı heykel var.'::text),
(319383,35487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A városnéző túráján három különböző szobor ...'::text,'van'::text,'van'::text,'lenni'::text,'A városnéző túráján három különböző szobor van.'::text),
(319395,35489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makelloses Selfie, klar. Sie ... warten, bis die Taube die Statue verlässt.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Makelloses Selfie, klar. Sie sollte warten, bis die Taube die Statue verlässt.'::text),
(319399,35489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганне селфі, звісно. Вона ... почекати, поки голуб полетить зі статуї.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Бездоганне селфі, звісно. Вона мала б почекати, поки голуб полетить зі статуї.'::text),
(319398,35489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selfie impecable, obviamente. ... esperar a que la paloma se vaya de la estatua.'::text,'Debería'::text,'Debería'::text,'Debería'::text,'Selfie impecable, obviamente. Debería esperar a que la paloma se vaya de la estatua.'::text),
(319397,35489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selfie parfait, évidemment. Elle ... attendre que le pigeon quitte la statue.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Selfie parfait, évidemment. Elle devrait attendre que le pigeon quitte la statue.'::text),
(319400,35489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz selfie, belli ki. Güvercin heykelden gidene kadar ...'::text,'beklemeli'::text,'beklemeli'::text,'beklemeli'::text,'Kusursuz selfie, belli ki. Güvercin heykelden gidene kadar beklemeli.'::text),
(319401,35489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan szelfi, nyilván. ... várnia, amíg a galamb elhagyja a szobrot.'::text,'Kellene'::text,'Kellene'::text,'Kellene'::text,'Hibátlan szelfi, nyilván. Kellene várnia, amíg a galamb elhagyja a szobrot.'::text),
(319404,35490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie liebt die riesige Statue, ... macht sie ihre Pose nach. Sehr unauffällig, klar.'::text,'also'::text,'weil'::text,'aber'::text,'Sie liebt die riesige Statue, also macht sie ihre Pose nach. Sehr unauffällig, klar.'::text),
(319408,35490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона обожнює величезну статую, ... копіює її позу. Дуже непомітно, звісно.'::text,'тому'::text,'бо'::text,'але'::text,'Вона обожнює величезну статую, тому копіює її позу. Дуже непомітно, звісно.'::text),
(319407,35490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le encanta la estatua gigante, ... copia su pose. Muy sutil, obviamente.'::text,'así que'::text,'porque'::text,'pero'::text,'Le encanta la estatua gigante, así que copia su pose. Muy sutil, obviamente.'::text),
(319406,35490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle adore la statue géante, ... elle copie sa pose. Très discret, évidemment.'::text,'donc'::text,'parce que'::text,'mais'::text,'Elle adore la statue géante, donc elle copie sa pose. Très discret, évidemment.'::text),
(319409,35490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev heykele bayılıyor, ... onun pozunu taklit ediyor. Çok ince, belli ki.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Dev heykele bayılıyor, bu yüzden onun pozunu taklit ediyor. Çok ince, belli ki.'::text),
(319410,35490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádja az óriási szobrot, ... utánozza a pózát. Nagyon feltűnésmentes, nyilván.'::text,'ezért'::text,'mert'::text,'de'::text,'Imádja az óriási szobrot, ezért utánozza a pózát. Nagyon feltűnésmentes, nyilván.'::text),
(305706,33968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mutter umarmt ihre Kinder ... Schultor.'::text,'am'::text,'auf dem'::text,'im'::text,'Die Mutter umarmt ihre Kinder am Schultor.'::text),
(305710,33968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мама обіймає своїх дітей ... шкільної брами.'::text,'біля'::text,'на'::text,'у'::text,'Мама обіймає своїх дітей біля шкільної брами.'::text),
(305709,33968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La madre abraza a sus hijos ... la puerta del colegio.'::text,'en'::text,'sobre'::text,'en'::text,'La madre abraza a sus hijos en la puerta del colegio.'::text),
(305708,33968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mère serre ses enfants dans ses bras ... portail de l''école.'::text,'au'::text,'sur le'::text,'dans le'::text,'La mère serre ses enfants dans ses bras au portail de l''école.'::text),
(305711,33968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anne çocuklarına okul kapısının ... sarılıyor.'::text,'önünde'::text,'üstünde'::text,'içinde'::text,'Anne çocuklarına okul kapısının önünde sarılıyor.'::text),
(305712,33968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anya az iskola ... öleli meg a gyerekeit.'::text,'kapujánál'::text,'kapuján'::text,'kapujában'::text,'Az anya az iskola kapujánál öleli meg a gyerekeit.'::text),
(305724,33970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht das Ende der Welt! Deine Mutter ... es besser machen!'::text,'wird'::text,'macht'::text,'machte'::text,'Nicht das Ende der Welt! Deine Mutter wird es besser machen!'::text),
(305728,33970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це не кінець світу! Твоя мама ... це краще!'::text,'зробить'::text,'робить'::text,'зробила'::text,'Це не кінець світу! Твоя мама зробить це краще!'::text),
(305727,33970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No es el fin del mundo! ¡Tu madre lo ... mejor!'::text,'hará'::text,'hace'::text,'hizo'::text,'¡No es el fin del mundo! ¡Tu madre lo hará mejor!'::text),
(305726,33970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est pas la fin du monde ! Ta mère ... tout aller mieux !'::text,'fera'::text,'fait'::text,'a fait'::text,'Ce n''est pas la fin du monde ! Ta mère fera tout aller mieux !'::text),
(305729,33970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dünyanın sonu değil! Annen onu daha iyi ...!'::text,'yapacak'::text,'yapar'::text,'yaptı'::text,'Dünyanın sonu değil! Annen onu daha iyi yapacak!'::text),
(305730,33970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem dől össze a világ! Anyukád jobbá ...!'::text,'fogja tenni'::text,'teszi'::text,'tette'::text,'Nem dől össze a világ! Anyukád jobbá fogja tenni!'::text),
(305742,33972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, sie hat gesagt, die Pfanne ist heiß, also ... die Mutter einen Pfannkuchen wenden.'::text,'wird'::text,'wird'::text,NULL::text,'Hör mal, sie hat gesagt, die Pfanne ist heiß, also wird die Mutter einen Pfannkuchen wenden.'::text),
(305746,33972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що сковорідка гаряча, тож мама ... млинець.'::text,'збирається перевернути'::text,'переверне'::text,NULL::text,'Слухай, вона сказала, що сковорідка гаряча, тож мама збирається перевернути млинець.'::text),
(305745,33972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dijo que la sartén está caliente, así que la madre ... una tortita.'::text,'va a dar la vuelta a'::text,'dará la vuelta a'::text,NULL::text,'Oye, dijo que la sartén está caliente, así que la madre va a dar la vuelta a una tortita.'::text),
(305744,33972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit que la poêle est chaude, donc la mère ... une crêpe.'::text,'va retourner'::text,'retournera'::text,NULL::text,'Écoute, elle a dit que la poêle est chaude, donc la mère va retourner une crêpe.'::text),
(305747,33972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, tavanın sıcak olduğunu söyledi, bu yüzden anne bir krep ...'::text,'çevirecek'::text,'çevirecek'::text,NULL::text,'Dinle, tavanın sıcak olduğunu söyledi, bu yüzden anne bir krep çevirecek.'::text),
(305748,33972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy forró a serpenyő, úgyhogy az anya meg ... fordítani egy palacsintát.'::text,'fog'::text,'fog'::text,NULL::text,'Figyelj, azt mondta, hogy forró a serpenyő, úgyhogy az anya meg fog fordítani egy palacsintát.'::text),
(305751,33973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, die Mutter macht so viel ... auf die Pfannkuchen.'::text,'Zucker'::text,'Zucker'::text,'einen Zucker'::text,'Mädel, ich hab gehört, die Mutter macht so viel Zucker auf die Pfannkuchen.'::text),
(305755,33973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, мама кладе на млинці стільки ...'::text,'цукру'::text,'цукру'::text,'цукру'::text,'Подруго, я чула, мама кладе на млинці стільки цукру.'::text),
(305754,33973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que la madre le pone tanto ... a las tortitas.'::text,'azúcar'::text,'azúcar'::text,'un azúcar'::text,'Tía, he oído que la madre le pone tanto azúcar a las tortitas.'::text),
(305753,33973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que la mère met tellement de ... sur les crêpes.'::text,'sucre'::text,'sucre'::text,'un sucre'::text,'Ma belle, il paraît que la mère met tellement de sucre sur les crêpes.'::text),
(305756,33973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki anne kreplerin üstüne o kadar çok ... koyuyormuş.'::text,'şeker'::text,'şekerler'::text,'bir şeker'::text,'Kızım, duydum ki anne kreplerin üstüne o kadar çok şeker koyuyormuş.'::text),
(305757,33973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy az anya annyi ... tesz a palacsintára.'::text,'cukrot'::text,'cukrot'::text,'egy cukrot'::text,'Csajszi, azt hallottam, hogy az anya annyi cukrot tesz a palacsintára.'::text),
(305760,33974,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mutter hat so ... Freizeit. Klar, ein total entspannter Tag.'::text,'viel'::text,'viele'::text,'eine Menge'::text,'Die Mutter hat so viel Freizeit. Klar, ein total entspannter Tag.'::text),
(305764,33974,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У мами так ... вільного часу. Звісно, дуже спокійний день.'::text,'багато'::text,'багато'::text,'багато'::text,'У мами так багато вільного часу. Звісно, дуже спокійний день.'::text),
(305763,33974,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La madre tiene ... tiempo libre. Obviamente, un día muy relajante.'::text,'tanto'::text,'tantos'::text,'un montón de'::text,'La madre tiene tanto tiempo libre. Obviamente, un día muy relajante.'::text),
(305762,33974,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mère a ... temps libre. Évidemment, une journée très reposante.'::text,'tellement de'::text,'tellement de'::text,'plein de'::text,'La mère a tellement de temps libre. Évidemment, une journée très reposante.'::text),
(305765,33974,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annenin o kadar ... boş vakti var. Belli ki çok dinlendirici bir gün.'::text,'çok'::text,'çok'::text,'çok'::text,'Annenin o kadar çok boş vakti var. Belli ki çok dinlendirici bir gün.'::text),
(305766,33974,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anyának olyan ... szabadideje van. Nyilván nagyon pihentető nap.'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Az anyának olyan sok szabadideje van. Nyilván nagyon pihentető nap.'::text),
(305769,33975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der Nähe der Mutter ... viele Eltern und Kinder.'::text,'sind'::text,'ist'::text,'sein'::text,'In der Nähe der Mutter sind viele Eltern und Kinder.'::text),
(305773,33975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Біля мами ... багато батьків і дітей.'::text,'є'::text,'є'::text,'бути'::text,'Біля мами є багато батьків і дітей.'::text),
(305772,33975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... muchos padres y niños cerca de la madre.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay muchos padres y niños cerca de la madre.'::text),
(305771,33975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... beaucoup de parents et d''enfants près de la mère.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a beaucoup de parents et d''enfants près de la mère.'::text),
(305774,33975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annenin yakınında bir sürü ebeveyn ve çocuk ...'::text,'var'::text,'var'::text,'olmak'::text,'Annenin yakınında bir sürü ebeveyn ve çocuk var.'::text),
(305775,33975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anya közelében sok szülő és gyerek ...'::text,'van'::text,'van'::text,'lenni'::text,'Az anya közelében sok szülő és gyerek van.'::text),
(305787,33977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... ein kleines grünes Motorrad, voll cool.'::text,'hat'::text,'haben'::text,'hat'::text,'Alter, er hat ein kleines grünes Motorrad, voll cool.'::text),
(305791,33977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... маленький зелений мотоцикл, це так круто.'::text,'має'::text,'мати'::text,'має'::text,'Бро, він має маленький зелений мотоцикл, це так круто.'::text),
(305790,33977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... una moto verde pequeña, qué guay.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Tío, tiene una moto verde pequeña, qué guay.'::text),
(305789,33977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... une petite moto verte, trop cool.'::text,'a'::text,'ont'::text,'a'::text,'Frère, il a une petite moto verte, trop cool.'::text),
(305792,33977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun küçük yeşil bir motosikleti ..., çok havalı.'::text,'var'::text,'var'::text,'var'::text,'Kanka, onun küçük yeşil bir motosikleti var, çok havalı.'::text),
(305793,33977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, neki ... egy kis zöld motorja, nagyon menő.'::text,'van'::text,'van'::text,'van'::text,'Tesó, neki van egy kis zöld motorja, nagyon menő.'::text),
(305796,33978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, der Typ ... jeden Tag Motorrad, muss Spaß machen.'::text,'fährt'::text,'fahren'::text,'fahrend'::text,'Alter, der Typ fährt jeden Tag Motorrad, muss Spaß machen.'::text),
(305800,33978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, цей хлопець ... на своєму мотоциклі щодня, мабуть, це кайф.'::text,'їздить'::text,'їздити'::text,'їдучи'::text,'Чувак, цей хлопець їздить на своєму мотоциклі щодня, мабуть, це кайф.'::text),
(305799,33978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, este chaval ... en su moto todos los días, tiene que ser divertido.'::text,'monta'::text,'montar'::text,'montando'::text,'Tío, este chaval monta en su moto todos los días, tiene que ser divertido.'::text),
(305798,33978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ce gars ... sa moto tous les jours, ça doit être fun.'::text,'conduit'::text,'conduire'::text,'conduisant'::text,'Mec, ce gars conduit sa moto tous les jours, ça doit être fun.'::text),
(305801,33978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu adam her gün motosikletine ..., kesin eğlencelidir.'::text,'biner'::text,'binmek'::text,'binerek'::text,'Kanka, bu adam her gün motosikletine biner, kesin eğlencelidir.'::text),
(305802,33978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ez a srác minden nap ... a motorjával, az biztos jó móka.'::text,'motorozik'::text,'motorozni'::text,'motorozó'::text,'Haver, ez a srác minden nap motorozik a motorjával, az biztos jó móka.'::text),
(305805,33979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das große Motorrad ... 200 Kilometer pro Stunde fahren. Ziel erreicht.'::text,'kann'::text,'kann'::text,'ist'::text,'Das große Motorrad kann 200 Kilometer pro Stunde fahren. Ziel erreicht.'::text),
(305809,33979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Великий мотоцикл ... їхати 200 кілометрів на годину. Ціль досягнута.'::text,'може'::text,'може'::text,'є'::text,'Великий мотоцикл може їхати 200 кілометрів на годину. Ціль досягнута.'::text),
(305808,33979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La moto grande ... ir a 200 kilómetros por hora. Objetivo cumplido.'::text,'puede'::text,'puede'::text,'está'::text,'La moto grande puede ir a 200 kilómetros por hora. Objetivo cumplido.'::text),
(305807,33979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La grosse moto ... rouler à 200 kilomètres à l''heure. Objectif atteint.'::text,'peut'::text,'peut'::text,'est'::text,'La grosse moto peut rouler à 200 kilomètres à l''heure. Objectif atteint.'::text),
(305810,33979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük motosiklet saatte 200 kilometre ...; hedefe ulaşıldı.'::text,'gidebilir'::text,'gidebilir'::text,NULL::text,'Büyük motosiklet saatte 200 kilometre gidebilir; hedefe ulaşıldı.'::text),
(305811,33979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy motor óránként 200 kilométerrel ... menni. Cél teljesítve.'::text,'tud'::text,'tud'::text,'van'::text,'A nagy motor óránként 200 kilométerrel tud menni. Cél teljesítve.'::text),
(305814,33980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fahrer haben viele ..., weil jeder Fahrer eins hat.'::text,'Motorräder'::text,'Motorrad'::text,'Motorräder'::text,'Die Fahrer haben viele Motorräder, weil jeder Fahrer eins hat.'::text),
(305818,33980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У райдерів багато ..., бо в кожного райдера є один.'::text,'мотоциклів'::text,'мотоцикл'::text,'мотоциклів'::text,'У райдерів багато мотоциклів, бо в кожного райдера є один.'::text),
(305817,33980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los moteros tienen muchas ... porque cada motero tiene una.'::text,'motos'::text,'moto'::text,'motos'::text,'Los moteros tienen muchas motos porque cada motero tiene una.'::text),
(305816,33980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les motards ont beaucoup de ... parce que chaque motard en a une.'::text,'motos'::text,'moto'::text,'motos'::text,'Les motards ont beaucoup de motos parce que chaque motard en a une.'::text),
(305819,33980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürücülerin çok sayıda ... var çünkü her sürücünün bir tane var.'::text,'motosiklet'::text,'motosiklet'::text,'motosikletler'::text,'Sürücülerin çok sayıda motosiklet var çünkü her sürücünün bir tane var.'::text),
(305820,33980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A motorosoknak sok ... van, mert minden motorosnak van egy.'::text,'motorja'::text,'motorja'::text,'motorja'::text,'A motorosoknak sok motorja van, mert minden motorosnak van egy.'::text),
(305832,33982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regeln sagen, jeder Fahrer ... auf dem Motorrad einen Helm tragen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Die Regeln sagen, jeder Fahrer muss auf dem Motorrad einen Helm tragen.'::text),
(305836,33982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правила кажуть, що кожен мотоцикліст ... носити шолом на мотоциклі.'::text,'має'::text,'мусить'::text,'мав би'::text,'Правила кажуть, що кожен мотоцикліст має носити шолом на мотоциклі.'::text),
(305835,33982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las normas dicen que todo motero ... llevar casco en la moto.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Las normas dicen que todo motero tiene que llevar casco en la moto.'::text),
(305834,33982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le règlement dit que chaque motard ... porter un casque à moto.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le règlement dit que chaque motard doit porter un casque à moto.'::text),
(305837,33982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurallara göre her sürücü motosiklette kask ...'::text,'takmak zorunda'::text,'takmalı'::text,'takmalı'::text,'Kurallara göre her sürücü motosiklette kask takmak zorunda.'::text),
(305838,33982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szabályok szerint minden motorosnak sisakot ... viselnie a motoron.'::text,'kell'::text,'kell'::text,'kellene'::text,'A szabályok szerint minden motorosnak sisakot kell viselnie a motoron.'::text),
(305841,33983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf der Küstenstraße ... die Fahrer langsam Motorrad fahren.'::text,'sollten'::text,'sollen'::text,'sollten'::text,'Auf der Küstenstraße sollten die Fahrer langsam Motorrad fahren.'::text),
(305845,33983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На прибережній дорозі мотоциклісти ... їздити на своїх мотоциклах повільно.'::text,'мали б'::text,'будуть'::text,'мали б'::text,'На прибережній дорозі мотоциклісти мали б їздити на своїх мотоциклах повільно.'::text),
(305844,33983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la carretera de la costa, los moteros ... ir despacio en sus motos.'::text,'deberían'::text,'deberán'::text,'deberían'::text,'En la carretera de la costa, los moteros deberían ir despacio en sus motos.'::text),
(305843,33983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sur la route côtière, les motards ... rouler lentement à moto.'::text,'devraient'::text,'devront'::text,'devraient'::text,'Sur la route côtière, les motards devraient rouler lentement à moto.'::text),
(305846,33983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahil yolunda sürücüler motosikletlerini yavaş ...'::text,'sürmeli'::text,'sürecekler'::text,'sürmeli'::text,'Sahil yolunda sürücüler motosikletlerini yavaş sürmeli.'::text),
(305847,33983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A parti úton a motorosoknak lassan ... motorozniuk.'::text,'kellene'::text,'kell'::text,'kellene'::text,'A parti úton a motorosoknak lassan kellene motorozniuk.'::text),
(299568,33286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lächelt ... Helfer an, weil Helfer die Leute sind, die helfen.'::text,'ihre'::text,'seine'::text,'seine'::text,'Sie lächelt ihre Helfer an, weil Helfer die Leute sind, die helfen.'::text),
(299572,33286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона усміхається ... помічникам, бо помічники — це люди, які допомагають.'::text,'своїм'::text,'своїм'::text,'своїм'::text,'Вона усміхається своїм помічникам, бо помічники — це люди, які допомагають.'::text),
(299571,33286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonríe a ... ayudantes, porque los ayudantes son las personas que ayudan.'::text,'sus'::text,'sus'::text,'sus'::text,'Sonríe a sus ayudantes, porque los ayudantes son las personas que ayudan.'::text),
(299570,33286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle sourit à ... aides, parce que les aides sont les gens qui aident.'::text,'ses'::text,'ses'::text,'ses'::text,'Elle sourit à ses aides, parce que les aides sont les gens qui aident.'::text),
(299573,33286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yardımcılarına gülümsüyor, çünkü yardımcılar yardım eden insanlardır.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Onun yardımcılarına gülümsüyor, çünkü yardımcılar yardım eden insanlardır.'::text),
(299574,33286,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rámosolyog a ..., mert a segítők azok, akik segítenek.'::text,'segítőire'::text,'segítőire'::text,'segítőire'::text,'Rámosolyog a segítőire, mert a segítők azok, akik segítenek.'::text),
(299577,33287,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kommen meine Helfer? Dieses Sofa ist ein Albtraum!'::text,'Wann'::text,'Wer'::text,'Was'::text,'Wann kommen meine Helfer? Dieses Sofa ist ein Albtraum!'::text),
(299581,33287,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... прийдуть мої помічники? Цей диван — жах!'::text,'Коли'::text,'Хто'::text,'Що'::text,'Коли прийдуть мої помічники? Цей диван — жах!'::text),
(299580,33287,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... vienen mis ayudantes? ¡Este sofá es una pesadilla!'::text,'Cuándo'::text,'Quién'::text,'Qué'::text,'¿Cuándo vienen mis ayudantes? ¡Este sofá es una pesadilla!'::text),
(299579,33287,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mes aides arrivent-ils ? Ce canapé est un cauchemar !'::text,'Quand'::text,'Qui'::text,'Que'::text,'Quand mes aides arrivent-ils ? Ce canapé est un cauchemar !'::text),
(299582,33287,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yardımcılarım ... geliyor? Bu kanepe bir kâbus!'::text,'ne zaman'::text,'kim'::text,'ne'::text,'Yardımcılarım ne zaman geliyor? Bu kanepe bir kâbus!'::text),
(299583,33287,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... jönnek a segítőim? Ez a kanapé egy rémálom!'::text,'Mikor'::text,'Ki'::text,'Mi'::text,'Mikor jönnek a segítőim? Ez a kanapé egy rémálom!'::text),
(299586,33288,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Sofa ist endlich ... Laster! Die Helfer sind fix und fertig!'::text,'im'::text,'auf dem'::text,'am'::text,'Das Sofa ist endlich im Laster! Die Helfer sind fix und fertig!'::text),
(299590,33288,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Диван нарешті ... вантажівці! Помічники без сил!'::text,'у'::text,'на'::text,'біля'::text,'Диван нарешті у вантажівці! Помічники без сил!'::text),
(299589,33288,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El sofá por fin está ... el camión! ¡Los ayudantes están destrozados!'::text,'en'::text,'sobre'::text,'a'::text,'¡El sofá por fin está en el camión! ¡Los ayudantes están destrozados!'::text),
(299588,33288,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canapé est enfin ... camion ! Les aides sont épuisés !'::text,'dans le'::text,'sur le'::text,'au'::text,'Le canapé est enfin dans le camion ! Les aides sont épuisés !'::text),
(299591,33288,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanepe sonunda kamyonun ...! Yardımcılar bitap düştü!'::text,'içinde'::text,'üstünde'::text,NULL::text,'Kanepe sonunda kamyonun içinde! Yardımcılar bitap düştü!'::text),
(299592,33288,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanapé végre a ...! A segítők teljesen kikészültek!'::text,'teherautóban'::text,'teherautón'::text,'teherautónál'::text,'A kanapé végre a teherautóban! A segítők teljesen kikészültek!'::text),
(299595,33289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau hat ... Helfer am Laster.'::text,'zwei'::text,'zweiten'::text,'Zweien'::text,'Die Frau hat zwei Helfer am Laster.'::text),
(299599,33289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У жінки біля вантажівки ... помічники.'::text,'два'::text,'другий'::text,'двійки'::text,'У жінки біля вантажівки два помічники.'::text),
(299598,33289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer tiene ... ayudantes en el camión.'::text,'dos'::text,'segundo'::text,'dos'::text,'La mujer tiene dos ayudantes en el camión.'::text),
(299597,33289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme a ... aides au camion.'::text,'deux'::text,'deuxième'::text,'deux'::text,'La femme a deux aides au camion.'::text),
(299600,33289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadının kamyonun yanında ... yardımcısı var.'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Kadının kamyonun yanında iki yardımcısı var.'::text),
(299601,33289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nőnek ... segítője van a teherautónál.'::text,'két'::text,'második'::text,'kettesek'::text,'A nőnek két segítője van a teherautónál.'::text),
(299604,33290,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Helfer ... das Sofa gemeinsam in den Laster.'::text,'schoben'::text,'schiebt'::text,'schieben'::text,'Die Helfer schoben das Sofa gemeinsam in den Laster.'::text),
(299608,33290,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Помічники разом ... диван у вантажівку.'::text,'заштовхали'::text,'штовхає'::text,'штовхають'::text,'Помічники разом заштовхали диван у вантажівку.'::text),
(299607,33290,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los ayudantes ... el sofá dentro del camión juntos.'::text,'empujaron'::text,'empuja'::text,'empujan'::text,'Los ayudantes empujaron el sofá dentro del camión juntos.'::text),
(299606,33290,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les aides ... le canapé dans le camion ensemble.'::text,'ont poussé'::text,'pousse'::text,'poussent'::text,'Les aides ont poussé le canapé dans le camion ensemble.'::text),
(299609,33290,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yardımcılar kanepeyi birlikte kamyona ...'::text,'ittiler'::text,'iter'::text,'iterler'::text,'Yardımcılar kanepeyi birlikte kamyona ittiler.'::text),
(299610,33290,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A segítők együtt ... be a kanapét a teherautóba.'::text,'tolták'::text,'tolja'::text,'tolják'::text,'A segítők együtt tolták be a kanapét a teherautóba.'::text),
(299622,33292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, die Helfer ... das Sofa in den Laster, ganz schön schwer.'::text,'schieben'::text,'schieben'::text,'schieben'::text,'Ey, die Helfer schieben das Sofa in den Laster, ganz schön schwer.'::text),
(299626,33292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, помічники ... той диван у вантажівку, важкенький.'::text,'штовхають'::text,'штовхають'::text,'штовхають'::text,'Йо, помічники штовхають той диван у вантажівку, важкенький.'::text),
(299625,33292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, los ayudantes ... ese sofá al camión, pesa bastante.'::text,'están empujando'::text,'empujan'::text,'están empujando'::text,'Oye, los ayudantes están empujando ese sofá al camión, pesa bastante.'::text),
(299624,33292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, les aides ... ce canapé dans le camion, un peu lourd.'::text,'sont en train de pousser'::text,'poussent'::text,'sont en train de pousser'::text,'Wesh, les aides sont en train de pousser ce canapé dans le camion, un peu lourd.'::text),
(299627,33292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yardımcılar o kanepeyi kamyona ..., baya ağır.'::text,'itiyor'::text,'iterler'::text,'itiyor'::text,'Kanka, yardımcılar o kanepeyi kamyona itiyor, baya ağır.'::text),
(299628,33292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a segítők ... azt a kanapét a teherautóba, elég nehéz.'::text,'tolják'::text,'tolják'::text,'tolják'::text,'Figyu, a segítők tolják azt a kanapét a teherautóba, elég nehéz.'::text),
(306273,34031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er spielt sonst zu Hause Musik, aber heute ... er auf der Straße.'::text,'spielt'::text,'spielt'::text,NULL::text,'Er spielt sonst zu Hause Musik, aber heute spielt er auf der Straße.'::text),
(306277,34031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він грає музику вдома, але сьогодні ... на вулиці.'::text,'грає'::text,'грає'::text,NULL::text,'Зазвичай він грає музику вдома, але сьогодні грає на вулиці.'::text),
(306276,34031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente toca música en casa, pero hoy ... en la calle.'::text,'está tocando'::text,'toca'::text,NULL::text,'Normalmente toca música en casa, pero hoy está tocando en la calle.'::text),
(306275,34031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il joue de la musique chez lui, mais aujourd''hui il ... dans la rue.'::text,'est en train de jouer'::text,'joue'::text,NULL::text,'D''habitude il joue de la musique chez lui, mais aujourd''hui il est en train de jouer dans la rue.'::text),
(306278,34031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde evde müzik çalar ama bugün sokakta ...'::text,'çalıyor'::text,'çalar'::text,NULL::text,'Genelde evde müzik çalar ama bugün sokakta çalıyor.'::text),
(306279,34031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában otthon zenél, de ma az utcán ...'::text,'zenél'::text,'zenél'::text,NULL::text,'Általában otthon zenél, de ma az utcán zenél.'::text),
(306282,34032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, seine Musik knallt. Ich glaube, dass die Menge für ihn ..., echt.'::text,'klatschen wird'::text,'klatscht'::text,'klatschte'::text,'Alter, seine Musik knallt. Ich glaube, dass die Menge für ihn klatschen wird, echt.'::text),
(306286,34032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, його музика — вогонь. Думаю, натовп ... йому, чесно.'::text,'зааплодує'::text,'аплодує'::text,'зааплодував'::text,'Бро, його музика — вогонь. Думаю, натовп зааплодує йому, чесно.'::text),
(306285,34032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, su música mola mucho. Creo que la gente le ..., en serio.'::text,'aplaudirá'::text,'aplaude'::text,'aplaudió'::text,'Tío, su música mola mucho. Creo que la gente le aplaudirá, en serio.'::text),
(306284,34032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, sa musique déchire. Je pense que la foule l''..., sérieux.'::text,'applaudira'::text,'applaudit'::text,'a applaudi'::text,'Frère, sa musique déchire. Je pense que la foule l''applaudira, sérieux.'::text),
(306287,34032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, müziği efsane. Bence kalabalık onu ..., cidden.'::text,'alkışlayacak'::text,'alkışlar'::text,'alkışladı'::text,'Kanka, müziği efsane. Bence kalabalık onu alkışlayacak, cidden.'::text),
(306288,34032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a zenéje nagyon üt. Szerintem a tömeg ... neki, komolyan.'::text,'tapsolni fog'::text,'tapsol'::text,'tapsolt'::text,'Tesó, a zenéje nagyon üt. Szerintem a tömeg tapsolni fog neki, komolyan.'::text),
(306291,34033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... 2 Stunden lang Musik spielen, um sein Ziel zu erreichen.'::text,'wird'::text,'spielt'::text,'wird'::text,'Er wird 2 Stunden lang Musik spielen, um sein Ziel zu erreichen.'::text),
(306295,34033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... музику 2 години, щоб досягти своєї мети.'::text,'збирається грати'::text,'грає'::text,'гратиме'::text,'Він збирається грати музику 2 години, щоб досягти своєї мети.'::text),
(306294,34033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... música durante 2 horas para alcanzar su objetivo.'::text,'Va a tocar'::text,'Toca'::text,'Tocará'::text,'Va a tocar música durante 2 horas para alcanzar su objetivo.'::text),
(306293,34033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de la musique pendant 2 heures pour atteindre son objectif.'::text,'va jouer'::text,'joue'::text,'jouera'::text,'Il va jouer de la musique pendant 2 heures pour atteindre son objectif.'::text),
(306296,34033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedefine ulaşmak için 2 saat müzik ...'::text,'çalacak'::text,'çalar'::text,'çalacak'::text,'Hedefine ulaşmak için 2 saat müzik çalacak.'::text),
(306297,34033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2 órán át ..., hogy elérje a célját.'::text,'zenélni fog'::text,'zenél'::text,'zenélni fog'::text,'2 órán át zenélni fog, hogy elérje a célját.'::text),
(306300,34034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat eine Gitarre, also ... er Musik machen, weil eine Gitarre Musik macht.'::text,'wird'::text,'wird'::text,NULL::text,'Er hat eine Gitarre, also wird er Musik machen, weil eine Gitarre Musik macht.'::text),
(306304,34034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У нього є гітара, тож він ... музику, бо гітара створює музику.'::text,'збирається грати'::text,'гратиме'::text,NULL::text,'У нього є гітара, тож він збирається грати музику, бо гітара створює музику.'::text),
(306303,34034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene una guitarra, así que ... música, porque una guitarra hace música.'::text,'va a tocar'::text,'tocará'::text,NULL::text,'Tiene una guitarra, así que va a tocar música, porque una guitarra hace música.'::text),
(306302,34034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a une guitare, donc il ... de la musique, parce qu''une guitare fait de la musique.'::text,'va jouer'::text,'jouera'::text,NULL::text,'Il a une guitare, donc il va jouer de la musique, parce qu''une guitare fait de la musique.'::text),
(306305,34034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gitarı var, bu yüzden müzik ..., çünkü gitar müzik yapar.'::text,'çalacak'::text,'çalacak'::text,NULL::text,'Gitarı var, bu yüzden müzik çalacak, çünkü gitar müzik yapar.'::text),
(306306,34034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy gitárja, ezért zenélni ..., mert a gitár zenét csinál.'::text,'fog'::text,'fog'::text,NULL::text,'Van egy gitárja, ezért zenélni fog, mert a gitár zenét csinál.'::text),
(306309,34035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mega Musik und kein ... im Gitarrenkoffer! Katastrophe!'::text,'Geld'::text,'Geld'::text,'ein Geld'::text,'Mega Musik und kein Geld im Gitarrenkoffer! Katastrophe!'::text),
(306313,34035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірна музика — і жодних ... у футлярі! Катастрофа!'::text,'грошей'::text,'грошей'::text,'грошей'::text,'Неймовірна музика — і жодних грошей у футлярі! Катастрофа!'::text),
(306312,34035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Música increíble y nada de ... en el estuche! ¡Desastre!'::text,'dinero'::text,'dinero'::text,'un dinero'::text,'¡Música increíble y nada de dinero en el estuche! ¡Desastre!'::text),
(306311,34035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une musique incroyable et pas ... dans l''étui ! Catastrophe !'::text,'d''argent'::text,'d''argent'::text,'d''un argent'::text,'Une musique incroyable et pas d''argent dans l''étui ! Catastrophe !'::text),
(306314,34035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika müzik ama kutuda hiç ... yok! Felaket!'::text,'para'::text,'paralar'::text,'bir para'::text,'Harika müzik ama kutuda hiç para yok! Felaket!'::text),
(306315,34035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elképesztő zene, és semmi ... a tokban! Katasztrófa!'::text,'pénz'::text,'pénz'::text,'egy pénz'::text,'Elképesztő zene, és semmi pénz a tokban! Katasztrófa!'::text),
(306318,34036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So ... Leute lieben seine Musik! Ich weine buchstäblich!'::text,'viele'::text,'viel'::text,'eine Menge'::text,'So viele Leute lieben seine Musik! Ich weine buchstäblich!'::text),
(306322,34036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Так ... людей люблять його музику! Я буквально плачу!'::text,'багато'::text,'багато'::text,'багато'::text,'Так багато людей люблять його музику! Я буквально плачу!'::text),
(306321,34036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... personas adoran su música! ¡Estoy literalmente llorando!'::text,'Tantas'::text,'Tanta'::text,'Un montón de'::text,'¡Tantas personas adoran su música! ¡Estoy literalmente llorando!'::text),
(306320,34036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gens adorent sa musique ! Je pleure littéralement !'::text,'Tellement de'::text,'Tellement de'::text,'Plein de'::text,'Tellement de gens adorent sa musique ! Je pleure littéralement !'::text),
(306323,34036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar ... insan onun müziğini seviyor! Resmen ağlıyorum!'::text,'çok'::text,'çok'::text,'çok'::text,'O kadar çok insan onun müziğini seviyor! Resmen ağlıyorum!'::text),
(306324,34036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan ... ember imádja a zenéjét! Szó szerint sírok!'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Olyan sok ember imádja a zenéjét! Szó szerint sírok!'::text),
(306327,34037,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nirgendwo ... bessere Musik! Ich schreie buchstäblich!'::text,'ist'::text,'sind'::text,'sein'::text,'Nirgendwo ist bessere Musik! Ich schreie buchstäblich!'::text),
(306331,34037,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніде ... кращої музики! Я буквально кричу!'::text,'немає'::text,'немає'::text,'бути'::text,'Ніде немає кращої музики! Я буквально кричу!'::text),
(306330,34037,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No ... mejor música en ningún sitio! ¡Estoy gritando literalmente!'::text,'hay'::text,'hay'::text,'hay'::text,'¡No hay mejor música en ningún sitio! ¡Estoy gritando literalmente!'::text),
(306329,34037,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pas de meilleure musique nulle part ! Je hurle littéralement !'::text,'Il n''y a'::text,'Il n''y a'::text,'Il n''y a'::text,'Il n''y a pas de meilleure musique nulle part ! Je hurle littéralement !'::text),
(306332,34037,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiçbir yerde daha iyi müzik ...! Resmen çığlık atıyorum!'::text,'yok'::text,'yok'::text,'olmak'::text,'Hiçbir yerde daha iyi müzik yok! Resmen çığlık atıyorum!'::text),
(306333,34037,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehol ... jobb zene! Szó szerint sikítok!'::text,'nincs'::text,'nincsenek'::text,'lenni'::text,'Sehol nincs jobb zene! Szó szerint sikítok!'::text),
(306444,34050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... bei jedem Länderspiel die Trommel spielen.'::text,'kann'::text,'kann'::text,'ist'::text,'Er kann bei jedem Länderspiel die Trommel spielen.'::text),
(306448,34050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... грати на барабані на кожному матчі збірної.'::text,'може'::text,'може'::text,'є'::text,'Він може грати на барабані на кожному матчі збірної.'::text),
(306447,34050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... tocar el tambor en cada partido de la selección.'::text,'puede'::text,'puede'::text,'está'::text,'Él puede tocar el tambor en cada partido de la selección.'::text),
(306446,34050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... jouer du tambour à chaque match de l''équipe nationale.'::text,'peut'::text,'peut'::text,'est'::text,'Il peut jouer du tambour à chaque match de l''équipe nationale.'::text),
(306449,34050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her milli maçta davul ...'::text,'çalabilir'::text,'çalabilir'::text,NULL::text,'Her milli maçta davul çalabilir.'::text),
(306450,34050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden válogatott meccsen ... dobolni.'::text,'tud'::text,'tud'::text,'van'::text,'Minden válogatott meccsen tud dobolni.'::text),
(306453,34051,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist die Nationalflagge? Sie ist über der Menge.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Wo ist die Nationalflagge? Sie ist über der Menge.'::text),
(306457,34051,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... національний прапор? Він над натовпом.'::text,'Де'::text,'Що'::text,'Хто'::text,'Де національний прапор? Він над натовпом.'::text),
(306456,34051,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está la bandera nacional? Está sobre la multitud.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¿Dónde está la bandera nacional? Está sobre la multitud.'::text),
(306455,34051,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est le drapeau national ? Il est au-dessus de la foule.'::text,'Où'::text,'Quoi'::text,'Qui'::text,'Où est le drapeau national ? Il est au-dessus de la foule.'::text),
(306458,34051,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ulusal bayrak ...? Kalabalığın üstünde.'::text,'nerede'::text,'ne'::text,'kim'::text,'Ulusal bayrak nerede? Kalabalığın üstünde.'::text),
(306459,34051,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van a nemzeti zászló? A tömeg fölött.'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Hol van a nemzeti zászló? A tömeg fölött.'::text),
(306462,34052,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, dass er sein Gesicht in den Nationalfarben ...'::text,'bemalte'::text,'bemalt'::text,'bemalend'::text,'Bestie, er hat mir erzählt, dass er sein Gesicht in den Nationalfarben bemalte.'::text),
(306466,34052,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, він сказав мені, що ... обличчя в національні кольори.'::text,'розмалював'::text,'розмальовує'::text,'розмальовуючи'::text,'Подружко, він сказав мені, що розмалював обличчя в національні кольори.'::text),
(306465,34052,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ... la cara con los colores nacionales.'::text,'se pintó'::text,'se pinta'::text,'pintándose'::text,'Amiga, me dijo que se pintó la cara con los colores nacionales.'::text),
(306464,34052,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit qu''il ... le visage aux couleurs nationales.'::text,'s''est peint'::text,'se peint'::text,'se peignant'::text,'Ma belle, il m''a dit qu''il s''est peint le visage aux couleurs nationales.'::text),
(306467,34052,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana dedi ki yüzünü milli renklere ...'::text,'boyadı'::text,'boyar'::text,'boyayarak'::text,'Kanka, bana dedi ki yüzünü milli renklere boyadı.'::text),
(306468,34052,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy nemzeti színekre ... az arcát.'::text,'festette'::text,'festi'::text,'festő'::text,'Csajszi, azt mondta, hogy nemzeti színekre festette az arcát.'::text),
(306480,34054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, du ... für die Nationalmannschaft trommeln.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Mal ehrlich, du solltest für die Nationalmannschaft trommeln.'::text),
(306484,34054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти ... грати на барабані для збірної.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Не брехатиму, ти мав би грати на барабані для збірної.'::text),
(306483,34054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... tocar el tambor para la selección.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'No te voy a mentir, deberías tocar el tambor para la selección.'::text),
(306482,34054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu ... jouer du tambour pour l''équipe nationale.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Sans mentir, tu devrais jouer du tambour pour l''équipe nationale.'::text),
(306485,34054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, milli takım için davul ...'::text,'çalmalısın'::text,'çalacaksın'::text,'çalmalısın'::text,'Yalan yok, milli takım için davul çalmalısın.'::text),
(306486,34054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, a válogatottnak ... dobolnod.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Nem hazudok, a válogatottnak kellene dobolnod.'::text),
(306489,34055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fans singen die Nationalhymne ...'::text,'fröhlich'::text,'fröhlich'::text,'fröhlich'::text,'Die Fans singen die Nationalhymne fröhlich.'::text),
(306493,34055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фанати співають національну пісню ...'::text,'щасливо'::text,'щасливий'::text,'щасливо'::text,'Фанати співають національну пісню щасливо.'::text),
(306492,34055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los aficionados cantan la canción nacional ...'::text,'felizmente'::text,'feliz'::text,'felizmente'::text,'Los aficionados cantan la canción nacional felizmente.'::text),
(306491,34055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les supporters chantent la chanson nationale ...'::text,'joyeusement'::text,'joyeux'::text,'joyeusement'::text,'Les supporters chantent la chanson nationale joyeusement.'::text),
(306494,34055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taraftarlar milli marşı ... söylüyor.'::text,'mutlu bir şekilde'::text,'mutlu'::text,'mutlu bir şekilde'::text,'Taraftarlar milli marşı mutlu bir şekilde söylüyor.'::text),
(306495,34055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szurkolók ... éneklik a nemzeti dalt.'::text,'boldogan'::text,'boldog'::text,'boldogan'::text,'A szurkolók boldogan éneklik a nemzeti dalt.'::text),
(306498,34056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er bemalt sein Gesicht, ... er seine Nationalmannschaft liebt.'::text,'weil'::text,'also'::text,'aber'::text,'Er bemalt sein Gesicht, weil er seine Nationalmannschaft liebt.'::text),
(306502,34056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він розмальовує обличчя, ... любить свою збірну.'::text,'бо'::text,'тому'::text,'але'::text,'Він розмальовує обличчя, бо любить свою збірну.'::text),
(306501,34056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se pinta la cara ... quiere a su selección.'::text,'porque'::text,'así que'::text,'pero'::text,'Se pinta la cara porque quiere a su selección.'::text),
(306500,34056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il se peint le visage ... aime son équipe nationale.'::text,'parce qu''il'::text,'donc il'::text,'mais il'::text,'Il se peint le visage parce qu''il aime son équipe nationale.'::text),
(306503,34056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzünü boyuyor ... milli takımını seviyor.'::text,'çünkü'::text,'bu yüzden'::text,'ama'::text,'Yüzünü boyuyor çünkü milli takımını seviyor.'::text),
(306504,34056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kifesti az arcát, ... szereti a válogatottját.'::text,'mert'::text,'ezért'::text,'de'::text,'Kifesti az arcát, mert szereti a válogatottját.'::text),
(309180,34354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder Mitbewohner ... ein kleines Foto von seinem Gesicht.'::text,'hat'::text,'haben'::text,'hat'::text,'Jeder Mitbewohner hat ein kleines Foto von seinem Gesicht.'::text),
(309184,34354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен сусід по квартирі ... маленьке фото свого обличчя.'::text,'має'::text,'мати'::text,'має'::text,'Кожен сусід по квартирі має маленьке фото свого обличчя.'::text),
(309183,34354,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada compañero de piso ... una foto pequeña de su cara.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Cada compañero de piso tiene una foto pequeña de su cara.'::text),
(309182,34354,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque colocataire ... une petite photo de son visage.'::text,'a'::text,'ont'::text,'a'::text,'Chaque colocataire a une petite photo de son visage.'::text),
(309185,34354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her ev arkadaşının yüzünün küçük bir fotoğrafı ...'::text,'var'::text,'var'::text,'var'::text,'Her ev arkadaşının yüzünün küçük bir fotoğrafı var.'::text),
(309186,34354,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden lakótársnak ... egy kis fotója az arcáról.'::text,'van'::text,'van'::text,'van'::text,'Minden lakótársnak van egy kis fotója az arcáról.'::text),
(309198,34356,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du klebst ... Foto auf Japan, und ehrlich, das Foto ist perfekt.'::text,'ein'::text,'ein'::text,'das'::text,'Du klebst ein Foto auf Japan, und ehrlich, das Foto ist perfekt.'::text),
(309202,34356,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти кладеш ... фото на Японію, і чесно, фото ідеальне.'::text,''::text,NULL::text,NULL::text,'Ти кладеш фото на Японію, і чесно, фото ідеальне.'::text),
(309201,34356,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pones ... foto sobre Japón y, sinceramente, la foto es perfecta.'::text,'una'::text,'una'::text,'la'::text,'Pones una foto sobre Japón y, sinceramente, la foto es perfecta.'::text),
(309200,34356,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu mets ... photo sur le Japon, et franchement, la photo est parfaite.'::text,'une'::text,'une'::text,'la'::text,'Tu mets une photo sur le Japon, et franchement, la photo est parfaite.'::text),
(309203,34356,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Japonya''ya ... fotoğraf koyuyorsun ve açıkçası fotoğraf mükemmel.'::text,'bir'::text,'bir'::text,NULL::text,'Japonya''ya bir fotoğraf koyuyorsun ve açıkçası fotoğraf mükemmel.'::text),
(309204,34356,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fotót teszel Japánra, és őszintén, a fotó tökéletes.'::text,'Egy'::text,'Egy'::text,'A'::text,'Egy fotót teszel Japánra, és őszintén, a fotó tökéletes.'::text),
(309207,34357,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deine Idee mit ... Fotos ist so smooth.'::text,'diesen'::text,'diesem'::text,'jenem'::text,'Deine Idee mit diesen Fotos ist so smooth.'::text),
(309211,34357,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоя ідея з ... фото така класна.'::text,'цими'::text,'цим'::text,'тим'::text,'Твоя ідея з цими фото така класна.'::text),
(309210,34357,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu idea con ... fotos es tan ingeniosa.'::text,'estas'::text,'esta'::text,'esa'::text,'Tu idea con estas fotos es tan ingeniosa.'::text),
(309209,34357,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton idée avec ... photos est trop stylée.'::text,'ces'::text,'cette'::text,'cette'::text,'Ton idée avec ces photos est trop stylée.'::text),
(309212,34357,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fotoğraflarla ilgili fikrin çok şık.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu fotoğraflarla ilgili fikrin çok şık.'::text),
(309213,34357,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon ügyes az ötleted ... a fotókkal.'::text,'ezekkel'::text,'ezzel'::text,'azzal'::text,'Nagyon ügyes az ötleted ezekkel a fotókkal.'::text),
(309216,34358,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau klebt ... Foto auf Afrika.'::text,'ihr'::text,'sein'::text,'sein'::text,'Die Frau klebt ihr Foto auf Afrika.'::text),
